let s=initialState(),tab='geometry',view='model',result=null,error='',modal=false,selected='L65',saved=false,renderTimer=null;
s.geometryMode='dimensions';s.rack=defaultRack(s);
let activeInput={path:'',label:'',tab:''},guideCollapsed=false,restoringInput=false,lastGuideSvg='';
let editingPipe='0.0',selectedJointTier=0,selectedJointEnd='column';
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('ja-JP',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const val=path=>path.split('.').reduce((o,k)=>o?.[k],s);
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('');
const field=(label,path,unit='',min='',step='any')=>`<label class="field"><span>${label}</span><div class="unitbox"><input type="number" data-path="${path}" value="${esc(val(path))}" ${min!==''?`min="${min}"`:''} step="${step}" aria-label="${label}">${unit?`<small>${unit}</small>`:''}</div></label>`;
const textField=(label,path,placeholder='')=>`<label class="field"><span>${label}</span><input data-path="${path}" value="${esc(val(path))}" placeholder="${placeholder}" aria-label="${label}"></label>`;
const select=(label,path,items)=>`<label class="field"><span>${label}</span><select data-path="${path}" aria-label="${label}">${options(items,val(path))}</select></label>`;
const sectionOpts=Object.entries(catalog).map(([k,v])=>[k,v.label]),matOpts=Object.entries(materials).map(([k,v])=>[k,v.label]),mountOpts=[['floor','床'],['wall','壁'],['ceiling','天井']];
const checkbox=(path,label)=>`<label class="selectline"><input type="checkbox" data-path="${path}" ${val(path)?'checked':''}>${label}</label>`;
const panel=(title,content,small='',cls='')=>`<section class="panel ${cls}"><div class="panel-title">${title}<small>${small}</small></div>${content}</section>`;
const shapeIcon=t=>`<svg viewBox="0 0 70 40" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round">${t==='portal'?'<path d="M12 34V8H58V34"/><path opacity=".35" d="M6 35h12m34 0h12"/>':`<path d="M15 34V8H58"/>${t==='brace'?'<path d="M15 32L58 8"/>':''}<path opacity=".35" d="M10 4v32"/>`}</svg>`;
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function run(){try{if(s.geometryMode==='dimensions')Object.assign(s,buildRack(s));result=analyze(s);error='';}catch(e){result=null;error=e.message;}}
function header(){return `<header class="topbar"><div class="brand"><span class="mark">⌁</span><div>SUPPORT STUDIO<small>PIPE SUPPORT ENGINEERING</small></div></div><div class="topright"><span class="private">◈ ブラウザ内で計算</span><span class="tag">BETA / 一次検討</span><span class="avatar">S</span></div></header>`;}
function nav(){return `<aside class="sidebar"><div class="workspace">DESIGN WORKSPACE</div>${[['geometry','⌑','形状・寸法'],['material','▱','鋼材・曲げ加工'],['loads','↓','荷重条件'],['bolts','⊙','ボルト接合'],['anchor','⊥','アンカー'],['report','▤','計算書']].map(([id,ic,label])=>`<button class="navbtn ${tab===id?'active':''}" data-tab="${id}"><span>${ic}</span>${label}</button>`).join('')}<div class="sidefoot"><strong><span class="dot"></span>平面フレーム解析</strong>寸法 mm ／ 荷重 kN<br>線形弾性・面内の一次検討<br><br><button class="small-btn" data-action="method" style="background:transparent;color:#bbd2c5;border-color:#42625b">計算方法・適用範囲 ↗</button><p>SUPPORT STUDIO<br>VERSION 2.0</p></div></aside>`;}
function render(){const focused=document.activeElement,focusPath=focused?.dataset?.path,focusTop=focusPath?focused.getBoundingClientRect().top:null,scrollBefore=window.scrollY;clearTimeout(renderTimer);run();document.title=`${s.name} | SUPPORT STUDIO`;
 $('#app').innerHTML=header()+`<div class="layout">${nav()}<main class="main"><div class="breadcrumb">ワークスペース <span>／ 配管架台の構造検討</span></div><div class="pagehead"><div><h1>${esc(s.name)}</h1><p>形状から固定部まで、架台の条件をひとつのモデルで検討。</p></div><div class="actions"><button data-action="load">読込</button><button data-action="save">↓ データ保存</button><button class="primary" data-action="export-report">▤ 計算書を出力</button></div></div><div class="report-head"><h1>${esc(s.name)}</h1>配管架台 構造一次検討書 ／ ${new Date().toLocaleDateString('ja-JP')}<br>平面線形弾性解析・設計承認用の最終計算書ではありません。</div><div class="subbar"><div class="tabs">${[['geometry','形状・寸法'],['material','鋼材・曲げ加工'],['loads','荷重'],['bolts','ボルト接合'],['anchor','アンカー'],['report','計算結果']].map(([id,t])=>`<button class="${tab===id?'active':''}" data-tab="${id}">${t}</button>`).join('')}</div><div class="revision">${saved?'ローカル保存済み':'入力と同時に再計算'} <span class="dot" style="margin-left:7px"></span></div></div>${error?`<div class="note danger engine-error" role="alert">計算できません：${esc(error)}</div>`:''}${workspaceContent()}<div class="footer-note"><span>ⓘ 面内の一次検討です。接合部・面外安定・基礎・局部座屈の最終確認が別途必要です。</span><button class="small-btn" data-action="method">計算根拠・適用範囲 ↗</button></div></main></div>${modal?`<div class="modal-back"><div class="modal" role="dialog" aria-modal="true" aria-label="計算方法と適用範囲"><div class="panel-title">計算方法と適用範囲<button data-action="close">閉じる ×</button></div><div class="large-body">${method()}</div></div></div>`:''}`;
 if(focusPath){const next=Array.from(document.querySelectorAll('[data-path]')).find(el=>el.dataset.path===focusPath);if(next){restoringInput=true;next.focus({preventScroll:true});restoringInput=false;window.scrollTo(0,scrollBefore+next.getBoundingClientRect().top-focusTop);}}
}
function legacyGeometry(){return `<div class="workgrid">${panel('架台の設定',`<div class="body"><div class="section-label"><span class="step-num">01</span>基本形状</div><div class="shape-picks two">${[['l','L型'],['portal','門型']].map(([k,t])=>`<button class="shape-pick ${(k==='l'?s.type!=='portal':s.type==='portal')?'active':''}" data-preset="${k}">${shapeIcon(k==='l'&&s.type==='brace'?'brace':k)}${t}</button>`).join('')}</div>${s.type!=='portal'?`<label class="field"><span>ブレース（形状更新時の設定）</span><select data-free-braced aria-label="ブレースの有無">${options([['yes','あり'],['no','なし']],s.type==='brace'?'yes':'no')}</select></label>`:''}<div class="section-label"><span class="step-num">02</span>取付面</div><div class="segmented">${mountOpts.map(([k,t])=>`<button data-mount="${k}" class="${s.mount===k?'active':''}">${t}</button>`).join('')}</div><div class="twocol">${field('幅 / 張出し W','w','mm',1)}${field('高さ H','h','mm',1)}</div><button data-action="regenerate" class="small-btn" style="width:100%">この寸法で形状を更新 ↗</button><p class="help">更新時は節点・部材・荷重をテンプレートに戻します。自由編集は下の表で行えます。</p><div class="sep"></div><div class="section-label"><span class="step-num">03</span>鋼材</div>${select('材質','material',matOpts)}${select('部材断面','defaultSection',sectionOpts)}<button data-action="apply-all" class="small-btn" style="width:100%">全ての部材に材質・断面を適用</button><div class="sep"></div>${textField('案件名','name')}<div class="note">部材は曲げ剛性を持つ平面フレームです。寸法モードで設定した梁柱の回転自由条件は保持します。</div></div>`,'PARAMETERS')}<div>${preview()}${summary()}${checks()}</div></div>${editor()}`;}
function preview(){if(tab!=='report')return '';return panel('構造モデル',`<div class="preview"><div class="preview-toolbar"><div class="mini-tabs"><button data-view="model" class="${view==='model'?'active':''}">形状</button><button data-view="deform" class="${view==='deform'?'active':''}">変形</button></div><span class="tag">2D · 正面図</span></div>${modelSvg()}<div class="legend"><span><i style="background:#678b7e"></i>鋼材</span><span><i style="background:#d87e5b"></i>外力</span><span>${s.geometryMode==='dimensions'?'● 配管 / ○ 接合点':'○ 節点'}</span><span style="margin-left:auto">mm</span></div></div>`,`${s.nodes.length} NODES / ${s.members.length} MEMBERS`);}
function modelSvg(guided=false){const drawView=guided?'model':view;if(error&&s.geometryMode==='dimensions')return '<div class="empty">寸法の入力エラーを修正すると構造図を更新します。</div>';const ns=s.nodes;if(!ns.length)return '<div class="empty">節点を追加してください。</div>';const pipes=s.geometryMode==='dimensions'?(s.pipeVisuals||[]):[],xs=ns.map(n=>n.x).concat(pipes.flatMap(p=>[p.x-p.outerWithInsulation/2,p.x+p.outerWithInsulation/2])),ys=ns.map(n=>n.y).concat(pipes.map(p=>p.y+p.outerWithInsulation));const minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),scale=Math.min(410/Math.max(maxx-minx,1),220/Math.max(maxy-miny,1));const ox=315-(minx+maxx)/2*scale,oy=205+(miny+maxy)/2*scale;const p=(n,dx=0,dy=0)=>[ox+(n.x+dx)*scale,oy-(n.y+dy)*scale];let content='';
 for(const n of ns){if(n.fix==='free')continue;const [x,y]=p(n);const rotate=n.mount==='wall'?90:n.mount==='ceiling'?180:0;content+=`<g transform="translate(${x} ${y}) rotate(${rotate})"><path d="M-22 6h44v12h-44z" fill="url(#hatch)" stroke="#c3cfc0"/><path d="M-25 5H25" stroke="#94a78d" stroke-width="2"/>${n.fix==='pin'?'<path d="M0 0l-8 5h16z" fill="#73896f"/>':'<rect x="-8" y="-5" width="16" height="10" rx="1" fill="#9aa995"/>'}<circle cx="-15" cy="4" r="2.2" fill="#6d7f65"/><circle cx="15" cy="4" r="2.2" fill="#6d7f65"/></g>`;}
 const factor=result&&result.maxDisp>0?Math.min(5000,25/(result.maxDisp*scale)):1;
 for(const m of s.members){const a=ns.find(n=>n.id===m.a),b=ns.find(n=>n.id===m.b);if(!a||!b)continue;const [x1,y1]=p(a),[x2,y2]=p(b);content+=`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${m.kind==='brace'?'#bd9774':'#637f70'}" stroke-width="${m.kind==='brace'?5:7}"/><line x1="${x1-1}" y1="${y1-1}" x2="${x2-1}" y2="${y2-1}" stroke="#9fb4a2" stroke-width="3"/>${s.geometryMode==='dimensions'?'':`<rect x="${(x1+x2)/2-12}" y="${(y1+y2)/2-26}" width="25" height="17" rx="4" fill="#f8fbf4" stroke="#d8e4d1"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-14}" text-anchor="middle" fill="#7d9376" font-size="9">M${m.id}</text>`}`;
 if(drawView==='deform'&&result){const rr=result.results.find(r=>r.id===m.id),L=rr.L,dx=b.x-a.x,dy=b.y-a.y,c=dx/L,d=dy/L;const path=[];for(let j=0;j<=30;j++){const t=j/30,u=rr.ul,xx=t*L;const q=s.selfWeight?-rr.p.A*1e-9*materials[m.material].rho*9.80665*s.factor:0;const ux=u[0]*(1-t)+u[3]*t+q*d*xx*(L-xx)/(2*materials[m.material].E*rr.p.A);const uy=(1-3*t*t+2*t**3)*u[1]+L*(t-2*t*t+t**3)*u[2]+(3*t*t-2*t**3)*u[4]+L*(-t*t+t**3)*u[5]+q*c*xx*xx*(L-xx)**2/(24*materials[m.material].E*rr.p.I);const pp=p({x:a.x+dx*t,y:a.y+dy*t},factor*(c*ux-d*uy),factor*(d*ux+c*uy));path.push(`${j?'L':'M'}${pp[0]} ${pp[1]}`);}content+=`<path d="${path.join(' ')}" stroke="#dc8465" stroke-width="2" fill="none" stroke-dasharray="6 4"/>`;}}
 if(s.geometryMode==='dimensions'){
  (s.braceVisuals||s.rack.braces).forEach((b,i)=>{const [x,y]=p({x:(b.ax+b.bx)/2,y:(s.mount==='ceiling'?-1:1)*(b.ay+b.by)/2});content+=`<rect x="${x+5}" y="${y-9}" width="23" height="15" rx="3" fill="#fff8ee" stroke="#dbba95"/><text x="${x+16}" y="${y+2}" text-anchor="middle" font-size="9" fill="#987448">B${i+1}</text>`;});
  for(const j of (s.jointVisuals||[])){if(j.joint==='weld')continue;const [x,y]=p(j);content+=`<rect x="${x-5}" y="${y-7}" width="10" height="14" rx="2" fill="#fff3d7" stroke="#a97b40"/><circle cx="${x}" cy="${y-3}" r="1.4" fill="#976a33"/><circle cx="${x}" cy="${y+3}" r="1.4" fill="#976a33"/>`; }
  for(const q of pipes){const [x,y]=p({x:q.x,y:q.y+q.outerWithInsulation/2}),radius=q.diameter/2*scale;content+=`${q.outerWithInsulation>q.diameter?`<circle cx="${x}" cy="${y}" r="${q.outerWithInsulation/2*scale}" fill="#f4e7c7" stroke="#c8ac77" stroke-width="1"/>`:""}<circle cx="${x}" cy="${y}" r="${radius}" fill="#e4f0ed" fill-opacity=".9" stroke="#478d81" stroke-width="1.4"/><text x="${x}" y="${y-radius-5}" text-anchor="middle" font-size="8" fill="#34796d">P${q.tier}-${q.number}</text>`;}
  s.rack.tiers.forEach((t,i)=>{const [x,y]=p({x:0,y:(s.mount==='ceiling'?-1:1)*t.height});content+=`<text x="${x-12}" y="${y-8}" text-anchor="end" font-size="9" fill="#548b7b">段${i+1} · ${fmt(t.height,0)}</text>`;});
  if(s.type==='portal'){for(const [name,xp] of [['左脚',s.rack.left],['右脚',s.rack.right]]){const [x,y]=p({x:xp,y:0});content+=`<text x="${x}" y="${y+(s.mount==='ceiling'?-16:28)}" text-anchor="middle" font-size="9" fill="#3d7362">${name} X=${fmt(xp,0)}</text>`;}}
 }
 for(const n of ns){if(s.geometryMode==='dimensions'&&s.jointVisuals?.some(j=>j.node===n.id&&j.joint!=='weld'))continue;const [x,y]=p(n);content+=`<circle cx="${x}" cy="${y}" r="4.2" fill="#f9fcf5" stroke="#557568" stroke-width="2"/>${s.geometryMode==='dimensions'?'':`<text x="${x+12}" y="${y+17}" fill="#81947a" font-size="10">${n.id}</text>`}`;}
 for(const l of s.loads){const n=ns.find(n=>n.id===l.node);if(!n)continue;const [x,y]=p(n);if(l.fy){const sign=l.fy>0?1:-1,top=y+sign*(s.geometryMode==='dimensions'?36:64),end=y+sign*13;content+=`<line x1="${x}" y1="${top}" x2="${x}" y2="${end}" stroke="#da7f5c" stroke-width="2" marker-end="url(#arrow)"/><text x="${x+9}" y="${top+4}" fill="#c87a57" font-size="11">${fmt(Math.abs(l.fy*s.factor),2)} kN</text>`;}if(l.fx){const sign=l.fx>0?1:-1;content+=`<line x1="${x-sign*60}" y1="${y-10}" x2="${x-sign*13}" y2="${y-10}" stroke="#da7f5c" stroke-width="2" marker-end="url(#arrow)"/><text x="${x-sign*60}" y="${y-23}" fill="#c87a57" font-size="10">Fx ${fmt(l.fx*s.factor)} kN</text>`;}if(l.mz)content+=`<text x="${x+15}" y="${y+33}" fill="#c87a57" font-size="10">↶ ${fmt(l.mz*s.factor)} kN·m</text>`;}
 const steelMinX=Math.min(...ns.map(n=>n.x)),steelMaxX=Math.max(...ns.map(n=>n.x)),steelMinY=Math.min(...ns.map(n=>n.y)),steelMaxY=Math.max(...ns.map(n=>n.y));const left=ox+steelMinX*scale,right=ox+steelMaxX*scale,bottom=oy-steelMinY*scale,top=oy-steelMaxY*scale;content+=`<path d="M${left} ${bottom+25}v18m0 -5H${right}m0 -13v18" stroke="#acbaa4" fill="none"/><text x="${(left+right)/2}" y="${bottom+54}" font-size="11" fill="#86987b" text-anchor="middle">${fmt(steelMaxX-steelMinX,0)}</text><path d="M${left-34} ${top}h-18m5 0V${bottom}m-5 0h18" stroke="#acbaa4" fill="none"/><text x="${left-54}" y="${(top+bottom)/2}" font-size="11" fill="#86987b" text-anchor="middle" transform="rotate(-90 ${left-54} ${(top+bottom)/2})">${fmt(steelMaxY-steelMinY,0)}</text>`;
 if(guided)content+=contextOverlay(currentInputContext(),p);
 return `<svg class="model" viewBox="${guided?`${left-65} ${top-48} ${right-left+140} ${bottom-top+115}`:'0 0 630 400'}" role="img" aria-label="架台の構造モデルと荷重"><defs><pattern id="hatch" width="7" height="7" patternUnits="userSpaceOnUse"><path d="M-1 7L7 -1M5 9L9 5" stroke="#c8d2bf" stroke-width="1"/></pattern><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#da7f5c"/></marker></defs>${content}<path d="M32 355v-29m0 29h29" stroke="#a0b295" stroke-width="1.3"/><text x="22" y="321" fill="#92a58a" font-size="9">Y</text><text x="65" y="359" fill="#92a58a" font-size="9">X</text><text x="600" y="378" text-anchor="end" font-size="9" fill="#8a9e7e">${drawView==='deform'&&result?'変形倍率 ×'+fmt(factor,0):'寸法に連動 / 正面投影'}</text></svg>`;
}
function summary(){return `<div class="summary">${[['最大応力度',result?.maxStress,'N/mm²',2],['最大変位',result?.maxDisp,'mm',3],['鋼材質量',result?.weight,'kg',2]].map(([label,v,unit,d])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-number">${fmt(v,d)}<small>${unit}</small></div><div class="metric-sub">${label==='最大応力度'?'軸力＋曲げの上限値':label==='最大変位'?'節点・部材内の合成変位':'形鋼・曲げ板のみ'}</div></div>`).join('')}</div>`;}
function checkRow(label,ratio){return `<div class="result-line"><span>${label}</span><div class="track ${ratio>1?'red':''}"><i style="width:${ratio===null||ratio===undefined?0:Math.min(100,ratio*100)}%"></i></div><span style="text-align:right">${ratio===null||ratio===undefined?'—':fmt(ratio,2)}</span><span class="badge ${ratio===null||ratio===undefined?'pending':ratio>1?'red':''}">${ratio===null||ratio===undefined?'条件未設定':ratio>1?'超過':'範囲内'}</span></div>`;}
function checks(){return panel('一次照査',`${checkRow('部材応力度',result?.memberRatio)}${checkRow('変位',result?.defRatio)}${checkRow('アンカー',result?.anchorRatio)}${s.geometryMode==='dimensions'&&s.rack.tiers.some(t=>connectionPositions(s).some(e=>jointType(t,e.key)!=='weld'))?`<div class="body note warning">ボルト・接合板：${boltOverview()}。接合部全体は未判定です。</div>`:''}<div class="body" style="padding-top:12px;padding-bottom:12px"><span class="help">比率 ＝ 計算値 / 入力限度値。総合的な構造安全性の判定は行いません。</span></div>`,'DEMAND / LIMIT','results');}
function editor(){return `<div class="full">${panel('自由形状エディタ',`<div class="body"><div class="note">節点座標と接続先を入力して形状を変更できます。Yは上向き正。交差する部材を接合する場合は、交点に節点を追加して部材を分割してください。</div></div><div class="table-wrap"><table><thead><tr><th>節点</th><th>X (mm)</th><th>Y (mm)</th><th>支点条件</th><th>取付面</th><th></th></tr></thead><tbody>${s.nodes.map((n,i)=>`<tr><td>N${n.id}</td><td><input type="number" data-path="nodes.${i}.x" value="${n.x}" aria-label="節点${n.id} X"></td><td><input type="number" data-path="nodes.${i}.y" value="${n.y}" aria-label="節点${n.id} Y"></td><td><select data-path="nodes.${i}.fix" aria-label="節点${n.id} 支点">${options([['free','自由'],['fixed','固定'],['pin','ピン']],n.fix)}</select></td><td><select data-path="nodes.${i}.mount" aria-label="節点${n.id} 取付面">${options(mountOpts,n.mount)}</select></td><td><button class="delete" data-delete="nodes.${i}" aria-label="節点${n.id}を削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-node">＋ 節点</button><span class="counter">${s.nodes.length} / 80</span></div><div class="table-wrap"><table><thead><tr><th>部材</th><th>始点</th><th>終点</th><th>断面</th><th>材質</th><th>有効長係数 K</th><th></th></tr></thead><tbody>${s.members.map((m,i)=>`<tr><td>M${m.id}</td>${['a','b'].map(k=>`<td><select data-path="members.${i}.${k}" data-number="true" aria-label="部材${m.id} ${k==='a'?'始点':'終点'}">${options(s.nodes.map(n=>[n.id,'N'+n.id]),m[k])}</select></td>`).join('')}<td><select class="wide" data-path="members.${i}.section" aria-label="部材${m.id} 断面">${options(sectionOpts,m.section)}</select></td><td><select data-path="members.${i}.material" aria-label="部材${m.id} 材質">${options(matOpts,m.material)}</select></td><td><input type="number" value="${m.k}" min="0.1" step="0.1" data-path="members.${i}.k" aria-label="部材${m.id} 有効長係数"></td><td><button class="delete" data-delete="members.${i}" aria-label="部材${m.id}を削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-member">＋ 部材</button><span class="counter">${s.members.length} / 160</span></div>`,'COORDINATES & CONNECTIONS')}</div>`;}
function sectionDrawing(p){if(p.kind==='BENT'&&p.points){const xs=p.points.map(v=>v[0]),ys=p.points.map(v=>v[1]),mi=Math.min(...xs),ma=Math.max(...xs),lo=Math.min(...ys),hi=Math.max(...ys),sc=Math.min(160/(ma-mi||1),110/(hi-lo||1));return `<svg class="section-svg" viewBox="0 0 280 160" role="img" aria-label="曲げ板断面"><path d="${p.points.map((q,i)=>`${i?'L':'M'}${140+(q[0]-(mi+ma)/2)*sc} ${80-(q[1]-(lo+hi)/2)*sc}`).join(' ')}" stroke="#69917a" stroke-width="${Math.max(3,s.bent.t*sc)}" fill="none" stroke-linejoin="miter"/><circle cx="${140+(p.cx-(mi+ma)/2)*sc}" cy="${80-(p.cy-(lo+hi)/2)*sc}" r="3" fill="#d57a56"/><text x="12" y="145" font-size="9" fill="#8a9d81">● 図心 / 曲げR省略</text></svg>`;}return `<svg class="section-svg" viewBox="0 0 280 160" role="img" aria-label="断面の模式図"><g transform="translate(95 30)" fill="#96b19a" stroke="#587f64" stroke-width="1.5">${p.kind==='L'?'<path d="M0 0h12v88h78v12H0z"/>':p.kind==='H'?'<path d="M0 0h90v12H51v76h39v12H0V88h39V12H0z"/>':p.kind==='C'?'<path d="M0 0h90v12H12v76h78v12H0z"/>':p.kind==='RECT'?'<path fill-rule="evenodd" d="M0 0h90v100H0zM9 9v82h72V9z"/>':'<path d="M0 0h90v100H0z"/>'}</g><text x="12" y="147" font-size="9" fill="#899e82">模式図・断面高さ方向に曲げ</text></svg>`;}
function material(){let p=null,pe='';try{p=section(s,selected);}catch(e){pe=e.message;}
 return `<div class="detailgrid"><div>${panel('断面ライブラリ',`<div class="large-body"><label class="field"><span>編集する断面</span><select id="section-edit">${options(sectionOpts,selected)}</select></label>${['RECT','H','C'].includes(selected)?`<div class="twocol">${field('高さ H','dims.h','mm',1)}${field('幅 B','dims.b','mm',1)}${field('板厚 / ウェブ t','dims.t','mm',.1)}${selected!=='RECT'?field('フランジ tf','dims.tf','mm',.1):''}</div><div class="note">任意寸法の矩形合成断面です。JIS形鋼の隅R・フランジ勾配を省略します。厳密な断面性能は「直接入力」で指定してください。</div>`:selected==='BENT'?`<div class="threecol">${field('板厚 t','bent.t','mm',.1)}${field('内R','bent.r','mm',0)}${field('K値','bent.k','',0,.01)}</div><div class="help">各辺は曲げ接線間の直線長。曲げ角は次の辺への回転角（反時計回り＋）。最終辺の曲げ角は使いません。</div><div class="table-wrap"><table><thead><tr><th>辺</th><th>直線長 mm</th><th>曲げ角 °</th><th></th></tr></thead><tbody>${s.bent.legs.map((l,i)=>`<tr><td>${i+1}</td><td><input type="number" data-path="bent.legs.${i}.length" value="${l.length}" min="1" aria-label="辺${i+1}直線長"></td><td>${i===s.bent.legs.length-1?'—':`<input type="number" data-path="bent.legs.${i}.turn" value="${l.turn}" min="-174" max="174" aria-label="辺${i+1}曲げ角">`}</td><td><button class="delete" data-delete="bent.legs.${i}" aria-label="辺${i+1}削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-leg">＋ 曲げ辺</button><button class="small-btn" data-bent="l">L断面</button><button class="small-btn" data-bent="u">コの字</button><button class="small-btn" data-bent="z">Z断面</button></div><div class="note warning">断面は直線要素近似です。曲げR部、断面の重なり、局部座屈・加工硬化は計算対象外。自己交差する断面には使用できません。</div>`:selected==='MANUAL'?`<div class="twocol">${field('断面積 A','manual.A','mm²',1)}${field('面内 I','manual.I','mm⁴',1)}${field('最小主軸 Imin','manual.Imin','mm⁴',1)}${field('断面係数 Z','manual.Z','mm³',1)}${field('せん断参照面積 Av','manual.Av','mm²',1)}</div>${textField('断面性能の出典','manualSource','メーカー名・資料名・版')}`:`<div class="note">JIS G 3192 等辺山形鋼の代表寸法。断面性能はJFE鋼材資料の掲載値です。SUS304は製品寸法・成形方法が一致する場合の幾何形状として使用します。</div>`}<div class="sep"></div><button class="primary" data-action="apply-section">この断面を全ての部材に適用</button><p class="help">部材ごとの断面・材質は「形状・寸法」の表で変更できます。寸法入力断面と曲げ断面は、種類ごとに共通の寸法を使用します。</p></div>`)}${panel('材質と照査限度',`<div class="body"><div class="note warning">許容応力度は設計基準・板厚・温度・荷重条件を確認して入力してください。0 の項目は未設定として扱います。</div>${matOpts.map(([m,t])=>`<div class="section-label" style="margin-top:18px">${t} <span class="counter">E = ${fmt(materials[m].E,0)} N/mm²</span></div><div class="twocol">${field('軸力＋曲げの限度','allow.'+m+'.normal','MPa',0)}${field('せん断の限度','allow.'+m+'.shear','MPa',0)}</div>`).join('')}<p class="material-hint">SSはSS400を実装。SUS304と建築構造用SUS304Aは同一の設計強度として扱えません。</p>${field('合成変位の限度','deflection','mm',.01)}</div>`,'USER DEFINED','full')}</div><div>${panel('断面プレビュー',`<div class="large-body">${p?sectionDrawing(p):`<div class="note danger">${esc(pe)}</div>`}${p?`<div class="stat-grid" style="margin-top:16px">${[['断面積 A',p.A,'mm²'],['面内 I',p.I,'mm⁴'],['断面係数 Z',p.Z,'mm³'],['最小主軸 Imin',p.Imin,'mm⁴'],['せん断参照面積 Av',p.Av,'mm²'],...(p.developed?[['展開長（概算）',p.developed,'mm']]:[])].map(([label,v,u])=>`<div class="stat"><small>${label}</small>${fmt(v,1)} <span class="muted">${u}</span></div>`).join('')}</div><p class="help">${esc(p.source)}。開断面はねじれ・面外変形を拘束した面内モデルです。</p>`:''}</div>`)}${preview()}${checks()}</div></div>`;
}
function loads(){if(s.geometryMode==='dimensions')return `<div class="detailgrid"><div>${panel('配管荷重',`<div class="large-body"><div class="note">各段の配管位置へ入力した荷重を載荷しています。配管荷重は「形状・寸法」で編集してください。</div><table><thead><tr><th>配管</th><th>節点</th><th>鉛直荷重 kN</th></tr></thead><tbody>${s.loads.map(l=>`<tr><td>P${l.tier}-${l.number}</td><td>N${l.node}</td><td>${fmt(l.fy)}</td></tr>`).join('')}</tbody></table><div class="sep"></div>${field('荷重倍率（自重にも適用）','factor','倍',.01)}${checkbox('selfWeight','鋼材自重を含める（鉛直下向き）')}<p class="help">配管荷重は各段の自動算定値または手入力値から集計します。水平力・モーメント等の追加編集は、現在の形状を保持して自由形状に切り替えて行えます。</p><button class="small-btn" data-action="rack-to-free">自由形状へ切り替えて荷重を編集</button></div>`)}${panel('設計メモ',`<div class="body"><label class="field"><span>荷重の根拠・検討条件</span><textarea data-path="note" rows="4">${esc(s.note)}</textarea></label></div>`,'','full')}</div><div>${preview()}${summary()}${checks()}</div></div>`;return `<div class="detailgrid"><div>${panel('荷重ケース',`<div class="large-body"><div class="note">Fxは右向き、Fyは上向き、Mzは反時計回りが正。配管・流体・保温材等の合計荷重を支持位置の節点に入力します。</div><div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>節点</th><th>Fx kN</th><th>Fy kN</th><th>Mz kN·m</th><th></th></tr></thead><tbody>${s.loads.map((l,i)=>`<tr><td><select data-path="loads.${i}.node" data-number="true" aria-label="荷重${i+1}節点">${options(s.nodes.map(n=>[n.id,'N'+n.id]),l.node)}</select></td>${['fx','fy','mz'].map(k=>`<td><input type="number" step="0.1" value="${l[k]}" data-path="loads.${i}.${k}" aria-label="荷重${i+1} ${k}"></td>`).join('')}<td><button class="delete" data-delete="loads.${i}" aria-label="荷重${i+1}削除">×</button></td></tr>`).join('')}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="add-load">＋ 荷重</button></div><div class="sep"></div>${field('荷重倍率（自重にも適用）','factor','倍',.01)}${checkbox('selfWeight','鋼材自重を含める（鉛直下向き）')}<p class="help">接合板・アンカー・溶接・配管の自重は自動集計しません。追加荷重として入力してください。地震・風・熱応力・振動の自動荷重生成や荷重組合せは未実装です。</p>${field('合成変位の限度','deflection','mm',.01)}</div>`)}${panel('設計メモ',`<div class="body"><label class="field slim"><span>荷重の根拠・検討条件</span><textarea data-path="note" rows="5" placeholder="例：満水時の配管重量、支持間隔、荷重の根拠資料…">${esc(s.note)}</textarea></label></div>`,'','full')}</div><div>${preview()}${summary()}${checks()}</div></div>`;}
function anchor(){const a=s.anchor,auto=a.capacityMode==='catalog',c=effectiveAnchorCapacity(a,{selfWeight:s.selfWeight||hasPipeDeadLoad(s)}),r=c.row;
 return `<div class="detailgrid"><div>${panel('固定部の条件',`<div class="large-body">${anchorProductFields()}<div class="sep"></div><div class="section-label">配置・母材</div><div class="twocol">${auto?'':field('呼び径','anchor.diameter','mm',1)+field('有効埋込み長さ','anchor.embed','mm',1)+field('コンクリート Fc','anchor.fc','MPa',1)}${field('1支点あたりの本数','anchor.count','本',2,2)}${field('2列間のピッチ','anchor.pitch','mm',1)}${a.count>2?field('各列内の最小ピッチ','anchor.columnPitch','mm',1):''}${field('最小へりあき','anchor.edge','mm',1)}${field('母材厚さ','anchor.thickness','mm',1)}${r?.source==='hst4'?field('実際の穿孔深さ','anchor.holeDepth','mm',1):''}</div><p class="help">同一本数を2列に等分し、全支点に共通の条件を適用。2列間のピッチは曲げに抵抗する距離です。</p>${r?`<div class="note">${r.hnom?'公称埋込み hnom = '+r.hnom+' mm。':''}${r.hmin?' 母材厚さ ≥ '+r.hmin+' mm。':''}${r.scr?' 引張の特性ピッチ ≥ '+r.scr+' mm、特性へりあき ≥ '+r.ccr+' mm。これらを満たしてもせん断端部・群効果は別途確認。':''}${r.smin?' 施工最小ピッチ '+r.smin+' mm、最小へりあき '+r.cmin+' mm（無低減の条件ではありません）。':''}${r.holeDepth?' 清掃付きハンマー穿孔 ≥ '+r.holeDepth+' mm、孔底から裏面 ≥ '+r.hb+' mm、締付トルク '+r.torque+' N·m。':''}</div>`:''}<div class="sep"></div>${auto?`${r?.source==='hy200'?`<div class="section-label">接着系の使用条件</div>${checkbox('anchor.sustained','配管重量などの持続荷重を含む')}<div class="twocol">${field('長期最高温度','anchor.tempLong','℃')}${field('短期最高温度','anchor.tempShort','℃')}</div><p class="help">架台自重または配管の自動重量を含む場合は、持続荷重として扱います。持続荷重は個別設計値を手入力してください。</p>`:''}${textField('適用品番・全長・仕様メモ','anchor.spec','実際に採用する品番')}${textField('施工・使用条件メモ','anchor.installation','穿孔・清掃、施工方向、温度・硬化時間等')}${textField('配置確認の根拠・計算書番号','anchor.layoutEvidence','群・端部・へりあきの影響を確認した資料')}${checkbox('anchor.layoutConfirmed','群・端部・へりあきの影響がなく、単独表値を使えることを別途確認済み')}${checkbox('anchor.installationConfirmed','適用品番・母材・施工条件・採用設計基準への適合を確認済み')}`:`<div class="section-label">個別設計・資料から入力する耐力</div><div class="twocol">${field('1本あたり 引張 Na','anchor.nt','kN',0)}${field('1本あたり せん断 Va','anchor.vt','kN',0)}</div><p class="help">群効果、ひび割れ、施工方向等を反映した値を入力してください。</p>${checkbox('anchor.confirmed','入力した耐力が実際の配置・施工条件に適用可能と確認済み')}`}</div>`,'全支点に共通')}</div><div>${panel(auto?'メーカー表から自動選択':'採用耐力',`<div class="large-body"><span class="tag">${auto?'完全一致の掲載値 / 1本あたり':'手入力 / 1本あたり'}</span><div class="capacity-values"><div><span>引張 ${r?.source==='hst4'||r?.source==='hy200'?'Nrec':'Na'}</span><strong>${fmt(c.nominalN)} <small>kN</small></strong></div><div><span>せん断 ${r?.source==='hst4'||r?.source==='hy200'?'Vrec':'Va'}</span><strong>${fmt(c.nominalV)} <small>kN</small></strong></div></div>${c.source?`<p><a href="${c.source.url}" target="_blank" rel="noopener">${esc(c.source.label)} ↗</a><br><span class="help">${esc(r.page?'PDF '+r.page+'頁':c.source.page)}</span></p><p>${esc(c.source.basis)}</p><div class="note">${esc(c.source.note)}</div>`:''}<div class="note ${c.ready?'':'warning'}" style="margin-top:14px"><strong>${c.ready?'参考照査に採用中':'表値の採用を保留'}</strong>${c.issues.length?'<ul>'+c.issues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>下記は簡易荷重配分による参考比率です。</p>'}</div>${c.advisories.map(x=>'<p class="help">'+esc(x)+'</p>').join('')}</div>`)}${panel('アンカーの参考照査',`<div class="body"><div class="note warning">支点反力からの簡易荷重配分です。ベースプレート曲げ・こじり力、群としての破壊耐力は別途確認が必要です。</div></div>${anchorTable()}<div class="body"><div class="method">引張 T = max(0, N) / n + 2|M| / (n p)<br>せん断 V = |Q| / n<br>照査比 = T / Na + V / Va<br><span class="help">圧縮による引張低減を見込まず、偶力間距離をpと仮定。製品指定の相関式・設計荷重体系との整合は別途確認してください。</span></div></div>`)}${preview()}</div></div>`;
}
function anchorTable(){return `<div class="table-wrap"><table><thead><tr><th>支点</th><th>取付</th><th>最大引張/本</th><th>せん断/本</th><th>比率</th><th>参考照査</th></tr></thead><tbody>${result?result.supports.map(r=>`<tr><td>N${r.id}</td><td>${mountOpts.find(x=>x[0]===r.mount)?.[1]||'—'}</td><td>${fmt(r.tension)} kN</td><td>${fmt(r.shear)} kN</td><td>${r.ratio===null?'—':fmt(r.ratio)}</td><td><span class="badge ${r.ratio===null?'pending':r.ratio>1?'red':''}">${r.ratio===null?'条件未設定':r.ratio>1?'超過':'範囲内'}</span></td></tr>`).join(''):'<tr><td colspan="6">計算結果なし</td></tr>'}</tbody></table></div>`;}
function report(){if(error)return panel('計算結果','<div class="body">入力エラーを修正して再計算してください。</div>');return `${panel('検討の状態',`<div class="body"><div class="note ${(result?.memberRatio>1||result?.anchorRatio>1||result?.defRatio>1||result?.euler>=1)?'danger':'warning'}">${error?'モデルの入力を修正してください。':result?.memberRatio>1||result?.anchorRatio>1||result?.defRatio>1?'入力限度を超えている項目があります。':result?.memberRatio===null||result?.anchorRatio===null?'許容値または製品条件が未設定のため、照査は未完了です。':'入力した限度内の一次検討結果です。最終設計には未評価項目の確認が必要です。'}${result?.euler>=1?' 弾性座屈荷重に達している部材があります。':''}</div></div>`)}<div class="detailgrid full"><div>${preview()}</div><div>${summary()}${checks()}</div></div>${panel('部材の解析結果',`<div class="table-wrap"><table><thead><tr><th>部材 / 材質</th><th>断面</th><th>長さ mm</th><th>|N| kN</th><th>|V| kN</th><th>|M| kN·m</th><th>σ MPa</th><th>τ参考 MPa</th><th>応力比</th><th>Nc / Ne</th></tr></thead><tbody>${result?result.results.map(r=>`<tr><td>M${r.id} / ${r.material}</td><td>${esc(r.p.label)}</td><td>${fmt(r.L,1)}</td><td>${fmt(r.N)}</td><td>${fmt(r.V)}</td><td>${fmt(r.M,3)}</td><td>${fmt(r.sigma)}</td><td>${fmt(r.tau)}</td><td>${r.ratio===null?'未設定':fmt(r.ratio)}</td><td>${fmt(r.euler,3)}</td></tr>`).join(''):'<tr><td colspan="10">計算結果なし</td></tr>'}</tbody></table></div><div class="body help">σ = max|N|/A + max|M|/Z（上限値）。τ = 1.5 max|V|/Av（参考値）。Nc/NeはEuler座屈荷重に対する比率で、設計用の座屈照査ではありません。</div>`,'部材内の最大値','full')}${s.geometryMode==='dimensions'?connectionResults():''}${panel('支点反力',`<div class="table-wrap"><table><thead><tr><th>支点</th><th>Rx kN</th><th>Ry kN</th><th>Mz kN·m</th></tr></thead><tbody>${result?result.supports.map(r=>`<tr><td>N${r.id}</td><td>${fmt(r.rx,3)}</td><td>${fmt(r.ry,3)}</td><td>${fmt(r.m,4)}</td></tr>`).join(''):''}</tbody></table></div>`,'X右＋ / Y上＋ / M反時計回り＋','full')}${panel('アンカー荷重・参考照査',anchorTable(),'','full')}${panel('計算条件・入力データ',`<div class="body print-condition">${conditions()}</div>`,'','full')}${panel('計算根拠・適用範囲',`<div class="large-body">${method()}</div>`,'','full')}`;}
function conditions(){return `${rackReport()}${pipeWeightReport()}${boltReport()}<p>案件：${esc(s.name)} ／ 荷重倍率：${fmt(s.factor)} ／ 自重：${s.selfWeight?'含む':'含まない'} ／ 変位限度：${fmt(s.deflection)} mm</p><p>${matOpts.map(([k])=>`${k}：E ${materials[k].E} N/mm²、ρ ${materials[k].rho} kg/m³、応力限度 ${s.allow[k].normal||'未設定'} MPa、せん断限度 ${s.allow[k].shear||'未設定'} MPa`).join('<br>')}</p><p>節点：${s.nodes.map(n=>`N${n.id} (${n.x}, ${n.y}) ${n.fix} / ${n.mount}`).join(' ／ ')}</p><p>部材：${s.members.map(m=>`M${m.id} N${m.a}→N${m.b}、${esc(catalog[m.section]?.label)}、${m.material}、K=${m.k}`).join('<br>')}</p><p>使用断面性能：${[...new Set(s.members.map(m=>m.section))].map(key=>{try{const p=section(s,key);return `${esc(p.label)}：A=${fmt(p.A,2)} mm²、I=${fmt(p.I,1)} mm⁴、Imin=${fmt(p.Imin,1)} mm⁴、Z=${fmt(p.Z,1)} mm³、Av=${fmt(p.Av,1)} mm²（${esc(p.source)}）`;}catch{return '断面不正';}}).join('<br>')}</p><p>入力荷重（倍率適用前）：${s.loads.map(l=>`N${l.node} Fx=${l.fx} kN, Fy=${l.fy} kN, Mz=${l.mz} kN·m`).join('<br>')||'なし'}</p><p>アンカー：${s.anchor.type==='metal'?'金属拡張':'接着系'} / ${esc(s.anchor.product)||'製品未指定'} / 呼び径 ${s.anchor.diameter} mm / ${s.anchor.count}本/支点 / ピッチ ${s.anchor.pitch} mm / 埋込み ${s.anchor.embed} mm / へりあき ${s.anchor.edge} mm / 母材厚 ${s.anchor.thickness} mm</p>${s.members.some(m=>m.section==='BENT')?`<p>曲げ板：t=${s.bent.t} mm、R=${s.bent.r} mm、K=${s.bent.k} ／ 直線長・次辺への角度 ${s.bent.legs.map(l=>`${l.length} mm / ${l.turn}°`).join('、')}</p>`:''}${anchorReportDetails()}<p>設計メモ：${esc(s.note).replace(/\n/g,'<br>')||'—'}</p>`;}
function method(){return `<div class="method"><h3>01　解析モデル</h3><p>2次元Euler–Bernoulliフレームの直接剛性法。各節点は水平変位・鉛直変位・回転を持ち、梁柱接合は選択した剛接／ピン条件を用います。ピン接合の梁回転は柱から分離し、同じ梁の左右区間は回転を共有して連続性を保持します。小変形・線形弾性・常温を仮定します。自重は部材に沿う等分布荷重として等価節点荷重と固定端力に反映します。部材内変位は101点の補間値、曲げ最大値は分布荷重による極値も評価します。</p><p>寸法入力モードは最大6段・各段8本の配管、最大8本のブレースに対応。配管中心位置と部材交点で部材を分割し、梁柱接合は各段の設定、その他の交点は剛接合とします。門型の脚位置は梁左端からの距離。配管本体は登録表の単位質量、内容物は内径断面積×入力密度、保温材は円環断面積×密度で計算し、負担長を掛けて載荷します。液体・気体とも管内容積全体に入力密度を適用します。参考密度は運転条件へ自動補正しません。圧縮空気・蒸気は実際の圧力・温度に対応する密度を入力してください。蒸気の凝縮水・水張り試験、熱膨張・内圧推力・水撃は自動計算しません。手入力荷重も選択できます。</p><h3>02　部材の参考照査</h3><p>軸力と曲げの応力度は |N|/A + |M|/Z の最大値の和で上限評価します。せん断は 1.5|V|/Av の簡易値です。Avは山形鋼の一辺の直線部、H・溝形はウェブ、角形は両ウェブ、曲げ板はA/2とした参照面積であり、一般断面の厳密なせん断分布は求めません。許容値は利用者の入力です。Euler荷重 Ne = π²EImin/(KL)² は参考表示のみです。</p><h3>03　断面と曲げ加工</h3><p>等辺山形鋼3種類はメーカー断面表の値。角形・H・溝形の寸法入力は矩形合成の近似断面です。曲げ板は直線中心線要素の面積・図心・二次モーメント・相乗モーメントからIminを求めます。断面係数は面内I/縁距離。断面は曲げR部分を省略し、展開長のみ各曲げの |θ| (R + Kt) を加算します。外寸法を直線長にそのまま入力しないでください。K値は実際の加工条件で補正が必要です。</p><h3>04　アンカー</h3><p>全支点に共通の2列均等配置を仮定。床・壁・天井の面法線に沿って支点反力を引張とせん断へ変換し、圧縮軸力の引張低減を見込まない荷重配分を使用します。T=max(0,N)/n+2|M|/(np)、V=|Q|/n。メーカー表の完全一致値、または入力した個別設計耐力に対する線形和で参考照査します。自動選択は製品・ロッド・径・有効埋込み・強度区分・ひび割れ・荷重区分を照合し、表のない組合せは保留します。HILTIの推奨荷重と日本の長短期許容荷重は区別します。群・端部・へりあきの影響を自動補正せず、別途確認の根拠がある場合のみ単独表値を採用します。HIT-HY 200 V3の登録表は非持続荷重用です。</p><h3>05　未評価の項目</h3><p>面外荷重・ねじり・非対称断面の非拘束曲げ・横座屈・局部座屈・設計用の圧縮座屈・接合部・溶接・ボルト・ベースプレート・こじり・コンクリート破壊・付着・群効果・基礎・耐震荷重組合せ・熱変形・疲労・振動・塑性化・2次効果は対象外。曲げ板の自己交差や製作可能性は確認が必要です。SUS304はSUS304Aの設計基準強度を流用しません。</p><h3>06　参照資料</h3><ul><li><a href="https://www.jfe-steel.co.jp/products/building/assets/pdf/shapes/angle-danmen.pdf" target="_blank" rel="noopener">JFEスチール：山形鋼の形状寸法・断面性能</a>（L50×50×6、L65×65×6、L75×75×6）</li><li><a href="https://www.nipponsteel.com/product/construction/handbook/pdf/3-35.pdf" target="_blank" rel="noopener">日本製鉄：建築構造材に使用されるステンレス鋼と接合材</a>（SUS304のE=193 GPa、密度7.93。炭素鋼E=205 GPaを入力モデルに使用）</li><li><a href="https://www.hilti.co.jp/engineering/articles/article-anchor-design-layout-and-installation" target="_blank" rel="noopener">Hilti：アンカー設計・配置と施工</a></li><li><a href="https://www.hilti.co.jp/engineering/articles/article-anchor-design-simple-calculation-example" target="_blank" rel="noopener">Hilti：アンカー設計の計算例</a>（耐力が製品・施工条件に依存することの参考）</li></ul><p>このアプリは上記資料やJISへの包括的な適合を認証するものではありません。案件の設計基準に基づく最終確認を行ってください。</p></div>`;}
function regenerate(){if(!(s.w>0&&s.h>0))return notify('幅と高さを正の値で入力してください。');Object.assign(s,preset(s.type,s.mount,s.w,s.h,s.defaultSection,s.material));s.anchor.layoutConfirmed=false;s.anchor.installationConfirmed=false;saved=false;render();}
function save(){run();if(error)return notify('入力エラーを修正してから保存してください。');const payload={...s,version:1};try{localStorage.setItem('support-studio-v1',JSON.stringify(payload));saved=true;}catch{}const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(s.name||'pipe-support').replace(/[<>:"/\\|?*]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);render();notify('検討データをJSONファイルに保存しました。');}
function loadState(data){if(!data||data.version!==1||!Array.isArray(data.nodes)||!Array.isArray(data.members)||!Array.isArray(data.loads)||!data.bent||!data.anchor||!data.allow)throw Error('対応する検討データではありません。');const forbidden=['__proto__','prototype','constructor'];function safe(o){if(o&&typeof o==='object')for(const k of Object.keys(o)){if(forbidden.includes(k))throw Error('不正なデータです。');safe(o[k]);}}safe(data);if(data.nodes.length>80||data.members.length>160||data.loads.length>100||data.bent.legs?.length>12)throw Error('データが上限を超えています。');data.anchor=normalizeAnchor(data.anchor);if(data.geometryMode===undefined)data.geometryMode='free';if(!['free','dimensions'].includes(data.geometryMode))throw Error('形状入力モードが不正です。');if(data.geometryMode==='dimensions'){data.rack=normalizeRack(data.rack);Object.assign(data,buildRack(data));}analyze(data);s=data;selected=s.defaultSection||'L65';saved=true;render();}
function handleField(e){const el=e.target;if(el.hasAttribute('data-rack-braced')){s.rack.braceMode=el.value==='yes'?'lower':'none';if(s.type!=='portal')s.type=el.value==='yes'?'brace':'l';invalidateRack();render();return;}if(el.hasAttribute('data-free-braced')){s.type=el.value==='yes'?'brace':'l';saved=false;render();return;}if(el.hasAttribute('data-joint-end')){selectedJointEnd=el.value;render();return;}if(el.hasAttribute('data-joint-tier')){selectedJointTier=Number(el.value);render();return;}if(el.id==='section-edit'){selected=el.value;render();return;}if(el.hasAttribute('data-rack-count')){s.rack=resizeTiers(s.rack,Number(el.value),s.h,s.w);invalidateRack();render();return;}const path=el.dataset.path;if(!path)return;if(path==='anchor.catalogId'){s.anchor=chooseAnchorProduct(s.anchor,el.value);saved=false;render();notify('製品表の掲載条件を選択しました。使用条件を確認してください。');return;}if(path==='anchor.capacityMode'){s.anchor=el.value==='catalog'?startAuto(s.anchor):{...s.anchor,capacityMode:'manual',nt:0,vt:0,confirmed:false};saved=false;render();return;}let target=s;const keys=path.split('.'),last=keys.pop();keys.forEach(k=>target=target[k]);if(el.type==='number'&&(el.value.trim()===''||el.validity.badInput)){clearTimeout(renderTimer);updateInputGuide();return;}const v=el.type==='checkbox'?el.checked:el.type==='number'||el.dataset.number?Number(el.value):el.value;if(typeof v==='number'&&!Number.isFinite(v))return notify('数値を入力してください。');const previousWeight=last==='loadMode'?safePipeWeight(target):null;target[last]=v;if((path.includes('.boltDesign.')||path.includes('.boltDesigns.'))){if(last==='method'){target.grade=v==='friction'?'F10T':'4.6';target.diameter=v==='friction'?16:12;target.hole=target.diameter+2;target.frictionConfirmed=false;}if(last==='diameter'){target.hole=v+2;target.fitConfirmed=false;}if(last==='grade'&&v==='S10T'&&target.diameter===12){target.diameter=16;target.hole=18;}if(['grade','frictionSurface','slipCoefficient'].includes(last))target.frictionConfirmed=false;}if(path.includes('.pipes.')){if(last==='fluidType')Object.assign(target,chooseFluid(v));if(last==='fluidDensity')target.fluidDensitySource='manual';if(last==='pipeType'&&v!=='custom'&&!pipeCatalog[v]?.rows.some(r=>r.nominal===target.nominal))target.nominal=pipeCatalog[v]?.rows[0]?.nominal;if(last==='loadMode'&&v==='manual'&&!previousWeight.error){target.load=previousWeight.load;target.diameter=previousWeight.diameter;}if(last==='insulation'&&v==='nichias')target.insulationDensity=90;}if(path.startsWith('rack.')||s.geometryMode==='dimensions'&&['w','h'].includes(path))invalidateRack();if(path==='anchor.diameter'&&s.anchor.capacityMode==='catalog'){const rs=rowsFor(s.anchor.catalogId).filter(r=>r.d===v);if(rs.length&&!rs.some(r=>r.hef===s.anchor.embed))s.anchor.embed=rs[0].hef;}if(path.startsWith('anchor.')){if(path!=='anchor.confirmed')s.anchor.confirmed=false;if(!['layoutConfirmed','installationConfirmed','layoutEvidence','spec','installation'].includes(last)){s.anchor.layoutConfirmed=false;s.anchor.installationConfirmed=false;}}if(path==='selfWeight'||path.startsWith('nodes.')&&last==='mount'){s.anchor.layoutConfirmed=false;s.anchor.installationConfirmed=false;}saved=false;clearTimeout(renderTimer);if(el.tagName==='SELECT'||el.type==='checkbox'){render();return;}renderTimer=setTimeout(()=>render(),e.type==='input'?550:160);}
document.addEventListener('pointerdown',()=>clearTimeout(renderTimer),true);
document.addEventListener('input',handleField);document.addEventListener('change',handleField);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.action==='toggle-guide'){guideCollapsed=!guideCollapsed;updateInputGuide();return;}
 if(d.boltTier!==undefined){selectedJointTier=Number(d.boltTier);if(d.boltEnd)selectedJointEnd=d.boltEnd;tab='bolts';render();return;}
 if(d.pipeEdit!==undefined){editingPipe=editingPipe===d.pipeEdit?'':d.pipeEdit;render();return;}if(d.rackType){s.type=d.rackType==='portal'?'portal':s.rack.braceMode==='none'?'l':'brace';invalidateRack();render();return;}
 if(d.rackMount){s.mount=d.rackMount;invalidateRack();render();return;}
 if(d.action==='rack-start'){s.geometryMode='dimensions';s.rack=defaultRack(s);invalidateRack();render();return;}
 if(d.action==='rack-to-free'){freezeRack();return;}
 if(d.rackAddPipe!==undefined){const t=s.rack.tiers[+d.rackAddPipe];if(t.pipes.length>=8)return notify('各段の配管は8本までです。');const sorted=[0,...t.pipes.map(p=>p.x).sort((a,b)=>a-b),s.w],gaps=sorted.slice(1).map((x,i)=>({gap:x-sorted[i],x:(x+sorted[i])/2}));gaps.sort((a,b)=>b.gap-a.gap);t.pipes.push(newPipe(Math.round(gaps[0].x*10)/10));editingPipe=d.rackAddPipe+'.'+(t.pipes.length-1);invalidateRack();render();return;}
 if(d.rackRemovePipe!==undefined){const [i,j]=d.rackRemovePipe.split('.').map(Number);s.rack.tiers[i].pipes.splice(j,1);invalidateRack();render();return;}
 if(d.rackSpace!==undefined){const ps=s.rack.tiers[+d.rackSpace].pipes;ps.forEach((p,i)=>p.x=Math.round(s.w*(i+1)/(ps.length+1)*10)/10);invalidateRack();render();return;}
 if(d.rackRemoveBrace!==undefined){s.rack.braces.splice(+d.rackRemoveBrace,1);invalidateRack();render();return;}
 if(d.action==='rack-add-brace'){s.rack.braceMode='custom';if(s.rack.braces.length>=8)return notify('ブレースは8本までです。');const left=s.type==='portal'?s.rack.left:0,t=s.rack.tiers[s.rack.braces.length%s.rack.tiers.length];s.rack.braces.push({ax:left,ay:Math.round(t.height*.35*10)/10,bx:s.type==='portal'?s.rack.right:s.w,by:t.height});invalidateRack();render();return;}
});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.view){view=b.dataset.view;render();return;}if(b.dataset.preset){s.type=b.dataset.preset==='portal'?'portal':s.type==='brace'?'brace':'l';regenerate();return;}if(b.dataset.mount){s.mount=b.dataset.mount;regenerate();return;}if(b.dataset.bent){const t=b.dataset.bent;s.bent.legs=t==='l'?[{length:50,turn:90},{length:80,turn:0}]:[{length:40,turn:90},{length:80,turn:t==='z'?-90:90},{length:40,turn:0}];saved=false;render();return;}if(b.dataset.delete){const keys=b.dataset.delete.split('.'),i=Number(keys.pop());let arr=s;keys.forEach(k=>arr=arr[k]);if(keys[0]==='nodes'){const id=s.nodes[i].id;if(s.members.some(m=>m.a===id||m.b===id)||s.loads.some(l=>l.node===id))return notify('接続する部材と荷重を先に削除してください。');}if(keys[0]==='bent'&&arr.length<=2)return notify('曲げ板には2辺以上が必要です。');arr.splice(i,1);saved=false;render();return;}
 switch(b.dataset.action){case 'regenerate':regenerate();break;case 'apply-all':s.members.forEach(m=>{m.section=s.defaultSection;m.material=s.material;});selected=s.defaultSection;saved=false;render();notify('全ての部材に適用しました。');break;case 'apply-section':s.defaultSection=selected;s.members.forEach(m=>m.section=selected);saved=false;render();notify('断面を全ての部材に適用しました。');break;case 'add-node':if(s.nodes.length>=80)return notify('節点は80個までです。');s.nodes.push({id:Math.max(0,...s.nodes.map(n=>n.id))+1,x:s.w,y:s.h,fix:'free',mount:s.mount});saved=false;render();break;case 'add-member':if(s.members.length>=160||s.nodes.length<2)return notify('部材上限または節点数を確認してください。');s.members.push({id:Math.max(0,...s.members.map(m=>m.id))+1,a:s.nodes[0].id,b:s.nodes[s.nodes.length-1].id,section:s.defaultSection,material:s.material,k:1});saved=false;render();break;case 'add-load':if(s.loads.length>=100)return notify('荷重は100件までです。');s.loads.push({node:s.nodes.at(-1)?.id,fx:0,fy:-1,mz:0});saved=false;render();break;case 'add-leg':if(s.bent.legs.length>=12)return notify('曲げ辺は12までです。');s.bent.legs.at(-1).turn=90;s.bent.legs.push({length:40,turn:0});saved=false;render();break;case 'save':save();break;case 'export-report':exportReport();break;case 'load':$('#file').click();break;case 'print':tab='report';modal=false;render();requestAnimationFrame(()=>window.print());break;case 'method':modal=true;render();break;case 'close':modal=false;render();break;}
});
$('#file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000){notify('1 MB以下の検討データを選んでください。');e.target.value='';return;}try{loadState(JSON.parse(await file.text()));notify('検討データを読み込みました。');}catch(err){notify('読み込めません：'+err.message);}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=false;render();}});
document.addEventListener('focusin',e=>{const el=e.target;if(restoringInput||!el.matches('input,select,textarea')||!el.closest('.guided-content'))return;activeInput={path:el.dataset.path||'',label:el.getAttribute('aria-label')||el.closest('label')?.querySelector('span')?.textContent||'入力条件',tab};updateInputGuide();if(window.innerWidth<1200){const box=document.getElementById('input-guide')?.getBoundingClientRect(),r=el.getBoundingClientRect();if(box&&r.top<box.bottom+12)window.scrollBy(0,r.top-box.bottom-18);}});
try{const stored=localStorage.getItem('support-studio-v1');if(stored)loadState(JSON.parse(stored));}catch{}render();

async function exportReport(){
 tab='report';modal=false;render();if(error)return notify('入力エラーを修正してから計算書を出力してください。');
 try{const css=await (await fetch('./style.css')).text();const html='<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(s.name)+' 構造一次検討書</title><style>'+css.replace(/@import[^;]+;/g,'')+'body{padding:24px}.main{max-width:1100px;padding:0}.preview-toolbar{display:none}.report-head{display:block}.no-print{margin-bottom:18px}@media print{body{padding:0}.no-print{display:none}}</style></head><body><main class="main"><div class="report-head"><h1>'+esc(s.name)+'</h1><p>配管架台 構造一次検討書 / '+new Date().toLocaleDateString('ja-JP')+'</p><p>平面線形弾性・参考計算。最終設計用の安全性判定ではありません。</p></div><button class="no-print primary" onclick="window.print()">印刷 / PDF保存</button>'+report()+'</main></body></html>';const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(s.name||'pipe-support').replace(/[<>:"/\\|?*]/g,'_')+'_計算書.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);notify('計算書をHTMLで保存しました。ブラウザで開くと印刷・PDF保存できます。');}catch(e){notify('計算書を保存できませんでした。再度お試しください。');}
}

function autoSelect(label,key,values,labels={},numeric=false){const value=s.anchor[key],items=[...new Set(values)].map(v=>[v,labels[v]||String(v)]);if(!items.some(([v])=>v===value))items.unshift([value,String(value)+'（未登録）']);return `<label class="field"><span>${label}</span><select data-path="anchor.${key}" ${numeric?'data-number="true"':''} aria-label="${label}">${options(items,value)}</select></label>`;}
function anchorProductFields(){
 const a=s.anchor,p=anchorProducts[a.catalogId],auto=a.capacityMode==='catalog',rows=rowsFor(a.catalogId);
 const product=`<label class="field"><span>メーカー・製品を選択</span><select data-path="anchor.catalogId" aria-label="メーカー・製品を選択"><option value="custom" ${!p?'selected':''}>その他 / 手入力</option>${['HILTI','サンコーテクノ'].map(m=>`<optgroup label="${m}">${Object.entries(anchorProducts).filter(([,q])=>q.maker===m).map(([id,q])=>`<option value="${id}" ${a.catalogId===id?'selected':''}>${esc(q.name)}</option>`).join('')}</optgroup>`).join('')}</select></label>`;
 const intro=p?`<div class="product-card"><div class="product-brand">${esc(p.maker)}<span>公式資料の掲載値を登録</span></div><h3>${esc(p.name)}</h3><p>${esc(p.material)}</p><a href="${p.url}" target="_blank" rel="noopener">公式製品情報 ↗</a></div>${select('耐力の設定方法','anchor.capacityMode',[['catalog','メーカー表から自動選択'],['manual','個別設計値を手入力']])}`:select('アンカーの種類','anchor.type',[['metal','金属拡張アンカー'],['chemical','接着系（ケミカル）アンカー']])+textField('メーカー・製品名','anchor.product');
 if(auto)return product+intro+`${p?.type==='chemical'?autoSelect('ロッド・材質強度区分','rodKey',rows.map(r=>r.rod),rodLabels):''}<div class="twocol">${autoSelect('呼び径','diameter',rows.map(r=>r.d),Object.fromEntries(rows.map(r=>[r.d,'M'+r.d])),true)}${autoSelect('有効埋込み長さ hef','embed',rows.filter(r=>r.d===a.diameter).map(r=>r.hef),{},true)}</div>${autoSelect('コンクリート強度区分','concreteKey',rows.map(r=>r.concrete),concreteLabels)}<div class="twocol">${autoSelect('コンクリートのひび割れ条件','crack',['uncracked','cracked'],{uncracked:'ひび割れなし',cracked:'ひび割れあり'})}${autoSelect('採用耐力の荷重区分','duration',[...rows.map(r=>r.duration),'seismic'],durationLabels)}</div><p class="help">埋込み単位：mm。登録した条件だけを使用し、補間・外挿は行いません。EN強度区分は日本のFcに自動換算しません。ロッド材質は架台材質と独立です。</p>`;
 return product+intro+textField('製品品番・ロッド仕様','anchor.spec')+textField('採用設計基準・版・荷重区分','anchor.basis')+textField('許容耐力の根拠資料・頁 / 計算書番号','anchor.source')+`<div class="twocol">${select('コンクリートのひび割れ条件','anchor.crack',[['unknown','未指定'],['uncracked','ひび割れなし'],['cracked','ひび割れあり']])}${select('採用耐力の荷重区分','anchor.duration',[['unknown','未指定'],...Object.entries(durationLabels)])}</div>`+textField('施工・使用条件メモ','anchor.installation');
}
function anchorReportDetails(){const a=s.anchor,p=anchorProducts[a.catalogId],c=effectiveAnchorCapacity(a,{selfWeight:s.selfWeight||hasPipeDeadLoad(s)}),r=c.row;return `<p>アンカー製品詳細：${p?esc(p.maker+' / '+p.name)+' / '+esc(p.material):'手入力'}<br>耐力設定：${a.capacityMode==='catalog'?'メーカー表の完全一致検索':'個別手入力'}<br>品番・ロッド仕様：${esc(a.spec)||'未記入'} / ${esc(rodLabels[a.rodKey]||'—')}<br>コンクリート：${a.capacityMode==='catalog'?esc(concreteLabels[a.concreteKey]||a.concreteKey):'Fc '+a.fc+' MPa'}<br>ひび割れ：${esc(({uncracked:'ひび割れなし',cracked:'ひび割れあり'})[a.crack]||'未指定')} / 荷重区分：${esc(durationLabels[a.duration]||a.duration)}<br>引張表値：${fmt(c.nominalN)} kN / せん断表値：${fmt(c.nominalV)} kN / 採用：${c.ready?'参考照査に採用':'保留'}<br>各列内ピッチ：${a.count>2?a.columnPitch+' mm':'2本配置のため対象外'} / 実際の穿孔深さ：${r?.source==='hst4'?a.holeDepth+' mm':'対象外'}${r?.hnom?'<br>公称埋込み hnom：'+r.hnom+' mm':''}${c.source?`<br>出典：<a href="${c.source.url}">${esc(c.source.label)}</a> / ${esc(r.page?'PDF '+r.page+'頁':c.source.page)}<br>表識別：${esc(r.id)}<br>設計体系：${esc(c.source.basis)}<br>適用条件：${esc(c.source.note)}`:`<br>採用設計基準：${esc(a.basis)||'未指定'}<br>根拠資料：${esc(a.source)||'未指定'}`}<br>施工・使用条件：${esc(a.installation)||'未記入'}${a.capacityMode==='catalog'?`<br>配置確認根拠：${esc(a.layoutEvidence)||'未記入'} / 配置確認：${a.layoutConfirmed?'済':'未'} / 施工・設計基準確認：${a.installationConfirmed?'済':'未'}${r?.source==='hy200'?`<br>持続荷重：${a.sustained||s.selfWeight?'含む':'含まない'} / 長期最高温度 ${a.tempLong}℃ / 短期最高温度 ${a.tempShort}℃`:''}`:'<br>適用条件確認：'+(a.confirmed?'済':'未')}<br>保留理由：${c.issues.map(esc).join('、')||'なし'}<br>${c.advisories.map(esc).join('<br>')}</p>`;}

function rackGeometry(){const r=s.rack;return `<div class="workgrid rack-grid"><div>${panel('寸法で架台を組み立てる',`<div class="body"><div class="section-label">01　架台と取付面</div><div class="shape-picks two">${[['l','L型'],['portal','門型']].map(([k,t])=>`<button class="shape-pick ${(k==='l'?s.type!=='portal':s.type==='portal')?'active':''}" data-rack-type="${k}">${shapeIcon(k==='l'&&r.braceMode!=='none'?'brace':k)}${t}</button>`).join('')}</div><label class="field"><span>ブレース</span><select data-rack-braced aria-label="ブレースの有無">${options([['yes','あり'],['no','なし']],r.braceMode==='none'?'no':'yes')}</select></label><div class="segmented">${mountOpts.map(([k,t])=>`<button data-rack-mount="${k}" class="${s.mount===k?'active':''}">${t}</button>`).join('')}</div><div class="twocol">${field('梁幅 / 張出し W','w','mm',1)}${field('柱の全高 H','h','mm',1)}</div><label class="field"><span>配管を載せる段数</span><select aria-label="配管を載せる段数" data-rack-count>${options(Array.from({length:6},(_,i)=>[i+1,(i+1)+'段']),r.tiers.length)}</select></label><p class="help">段数変更時は全高で等間隔に配置します。各段の高さは下の表で変更できます。</p>${checkbox('rack.tipTie','各段の先端同士を縦材でつなぐ')}<p class="help">2段以上のとき、梁の右端（X=W）を縦材で一直線につなぎます。縦材は最下段から最上段までで、床・天井への支点は追加しません。縦材の断面・材質は下の指定を使います。</p>${s.type==='portal'?`<div class="section-label">02　門型の脚位置</div><div class="twocol">${field('左脚位置 X','rack.left','mm',0)}${field('右脚位置 X','rack.right','mm',0)}</div><div class="note">梁左端を X=0 とします。左右の脚を梁の内側に移すと張出し梁になります。脚間：${fmt(r.right-r.left,0)} mm。</div>`:''}<div class="sep"></div>${select('材質','material',matOpts)}${select('部材断面','defaultSection',sectionOpts)}${textField('案件名','name')}<p class="help">寸法入力中は全ての部材に上の材質・断面を適用します。部材ごとに変える場合は、形状を決めてから自由形状へ切り替えてください。</p><button class="small-btn" data-action="rack-to-free">現在の形状を自由形状で編集</button></div>`,'寸法に連動して再計算')}</div><div class="rack-preview">${preview()}<div class="note" style="margin-top:12px">${s.mount==='ceiling'?'天井取付：Y=0を天井とし、入力する高さは下向き距離です。配管荷重は鉛直下向きに作用します。':s.mount==='wall'?'壁取付：高さは下側基準から上向き。L型は柱の上下端、門型は左右脚の下端を壁へ固定します。':'床取付：Y=0を床とし、高さは上向きです。脚の下端を固定します。'}<br>図には保温外径も反映します。ボルト記号は接合位置です。「ボルト接合」で条件・計算対象の耐力を確認できます。金具・鋼材の納まりは実寸法で確認してください。</div>${(s.rackWarnings||[]).map(w=>`<div class="note warning" style="margin-top:8px">${esc(w)}</div>`).join('')}${summary()}${checks()}</div></div>${rackTierEditor()}${rackBraceEditor()}${connectionResults()}`;}
function rackBraceEditor(){return panel('ブレースの取付位置',`<div class="body">${s.rack.braceMode==='none'?'<div class="note">ブレースなし。上の「ブレースの有無」で「あり」にすると位置を設定できます。</div>':select('ブレースの配置','rack.braceMode',[['lower','下段のみ（段の高さに追従）'],['custom','自由な位置を指定']])}${s.rack.braceMode==='lower'?`<div class="twocol">${hasTipTie(s)?`<div class="note">下段ブレースの梁側は先端 X=${fmt(s.w,1)} mm に接続します。</div>`:field('下段ブレース 梁側X','rack.braceX','mm',1)}${field('柱側との高さ差','rack.braceDrop','mm',1)}</div><p class="help">斜めブレースは最下段だけに接続します。先端縦材を有効にすると、上段の先端は縦材を通じて下段につながります。高さ差は取付可能な範囲までに制限します。床・壁は下段の下側、天井は最下段のすぐ上の区間へ配置します。</p>${s.braceVisuals?.[0]?`<div class="note">実際の取付：(${fmt(s.braceVisuals[0].ax,1)}, ${fmt(s.braceVisuals[0].ay,1)}) → (${fmt(s.braceVisuals[0].bx,1)}, ${fmt(s.braceVisuals[0].by,1)}) mm / 高さ差 ${fmt(Math.abs(s.braceVisuals[0].by-s.braceVisuals[0].ay),1)} mm</div>`:''}`:''}</div>${s.rack.braceMode!=='custom'?'':`<div class="body"><div class="note">両端のXと高さを入力してください。Xは梁左端からの距離。高さの基準は各段と共通です。両端を柱・梁上に指定すると、その位置で部材を分割して接続します。交差する部材は交点で剛接合します。</div></div><div class="table-wrap"><table><thead><tr><th>ブレース</th><th>始点 X mm</th><th>始点 高さ mm</th><th>終点 X mm</th><th>終点 高さ mm</th><th>長さ mm</th><th></th></tr></thead><tbody>${s.rack.braces.map((b,i)=>`<tr><td>B${i+1}</td>${[['ax','始点X'],['ay','始点高さ'],['bx','終点X'],['by','終点高さ']].map(([k,label])=>`<td><input type="number" step="any" min="0" value="${b[k]}" data-path="rack.braces.${i}.${k}" aria-label="ブレース${i+1} ${label}"></td>`).join('')}<td>${fmt(Math.hypot(b.bx-b.ax,b.by-b.ay),1)}</td><td><button class="delete" data-rack-remove-brace="${i}" aria-label="ブレース${i+1}を削除">×</button></td></tr>`).join('')||'<tr><td colspan="7">ブレースなし。「追加」で任意の取付位置を設定できます。</td></tr>'}</tbody></table></div><div class="table-actions"><button class="small-btn" data-action="rack-add-brace">＋ ブレースを追加</button><span class="counter">${s.rack.braces.length} / 8</span></div>`}`,'下段のみ / 直付け / 自由位置','full');}
function geometry(){return s.geometryMode==='dimensions'?rackGeometry():`<div class="note" style="margin-bottom:16px">自由形状モードです。多段・配管配置・ブレース・脚位置を寸法で作る場合：<button class="small-btn" data-action="rack-start">寸法入力を開始（形状・荷重を置換）</button></div>`+legacyGeometry();}
function invalidateRack(){s.anchor.layoutConfirmed=false;s.anchor.installationConfirmed=false;s.anchor.confirmed=false;saved=false;}
function freezeRack(){if(error)return notify('入力エラーを修正してから切り替えてください。');s.members.forEach(m=>{if(m.physicalLength){const a=s.nodes.find(n=>n.id===m.a),b=s.nodes.find(n=>n.id===m.b);m.k=m.k*m.physicalLength/Math.hypot(b.x-a.x,b.y-a.y);delete m.physicalLength;delete m.group;delete m.kind;}});s.geometryMode='free';s.jointVisuals=[];s.braceVisuals=[];s.pipeVisuals=[];s.rackWarnings=[];saved=false;render();notify('現在の形状と荷重を保持して自由形状へ切り替えました。');}
function rackReport(){if(s.geometryMode!=='dimensions')return '';return `<p><strong>多段架台・寸法入力</strong><br>梁幅 ${s.w} mm / 柱全高 ${s.h} mm / ${s.rack.tiers.length}段 / 高さ基準：${s.mount==='ceiling'?'天井から下向き':'下端基準から上向き'}${s.type==='portal'?`<br>左脚 X=${s.rack.left} mm / 右脚 X=${s.rack.right} mm / 脚間 ${s.rack.right-s.rack.left} mm`:''}</p>${s.rack.tiers.map((t,i)=>`<p>段${i+1}：高さ ${t.height} mm<br>${t.pipes.map((p,j)=>`P${i+1}-${j+1}：中心 X=${p.x} mm / 外径 ${pipeWeight(p).diameter} mm / 架台負担荷重 ${fmt(pipeWeight(p).load,4)} kN`).join('<br>')||'配管なし'}</p>`).join('')}<p>先端の縦つなぎ：${hasTipTie(s)?`あり / X=${s.w} mm / 高さ ${Math.min(...s.rack.tiers.map(t=>t.height))}〜${Math.max(...s.rack.tiers.map(t=>t.height))} mm（既存柱と重なる場合は柱を兼用）`:'なし'}<br>ブレース：${(s.braceVisuals||s.rack.braces).map((b,i)=>`B${i+1}：(${b.ax}, ${b.ay}) → (${b.bx}, ${b.by}) mm / 長さ ${fmt(Math.hypot(b.bx-b.ax,b.by-b.ay))} mm`).join('<br>')||'なし'}<br>梁と柱・先端縦材の接合は各段・各接合位置の個別条件、縦材の上下および他の交点は剛接合。配管荷重は支持高さの節点に鉛直載荷。配管・内容物・保温材は架台鋼材の質量表示とは別に集計します。部材分割でEuler参考長さを短縮せず、各元部材の全長を使用します。</p>${(s.rackWarnings||[]).map(w=>'<p>配置注意：'+esc(w)+'</p>').join('')}`;}

function safePipeWeight(p){try{return pipeWeight(p);}catch(e){return {error:e.message,label:'入力を確認',load:null,diameter:p.diameter||0,outerWithInsulation:p.diameter||0};}}
function pipeConfig(i,j){
 const p=s.rack.tiers[i].pipes[j],base=`rack.tiers.${i}.pipes.${j}`,tag=`段${i+1} 配管${j+1}`,key=i+'.'+j;Object.assign(p,fluidInput(p));const w=safePipeWeight(p),fluid=fluidCatalog[p.fluidType];
 return `<div class="pipe-config"><div class="pipe-heading"><strong>P${i+1}-${j+1}</strong><span>${esc(w.label)} · ${p.loadMode==='auto'?esc(fluid?.label||'内容物を確認')+' · ':''}${fmt(w.load,3)} kN</span><button class="delete" data-rack-remove-pipe="${key}" aria-label="${tag}を削除">×</button></div>
 <div class="twocol">${field(`${tag} 中心X`,base+'.x','mm',0)}${select(`${tag} 荷重設定`,base+'.loadMode',[['auto','材質・寸法から自動計算'],['manual','荷重を手入力']])}</div>
 ${p.loadMode==='auto'?`<div class="pipe-main-fields"><div class="section-label">この配管の材質・サイズ・内容物</div><div class="twocol">
 ${select(`${tag} 材質・規格`,base+'.pipeType',[...Object.entries(pipeCatalog).map(([k,v])=>[k,v.label]),['custom','その他・実寸法 / 単位質量を入力']])}
 ${p.pipeType!=='custom'?`<label class="field"><span>${tag} 呼び径</span><select data-path="${base}.nominal" data-number="true" aria-label="${tag} 呼び径">${options((pipeCatalog[p.pipeType]?.rows||[]).map(r=>[r.nominal,r.nominal+'A']),p.nominal)}</select></label>`:textField(`${tag} 材質名`,base+'.customMaterial')}</div>
 ${p.pipeType==='custom'?`<div class="threecol">${field(`${tag} 実外径`,base+'.customOuter','mm',.1)}${field(`${tag} 肉厚`,base+'.customWall','mm',.1)}${field(`${tag} 配管密度`,base+'.customDensity','kg/m³',1)}</div>${select(`${tag} 本体質量の算出方法`,base+'.customMassMode',[['geometry','外径・肉厚・密度で計算'],['mass','メーカー単位質量を入力']])}${p.customMassMode==='mass'?field(`${tag} 本体単位質量`,base+'.customMass','kg/m',0):''}`:''}
 <p class="help">外径 ${fmt(w.diameter,1)} mm / 肉厚 ${fmt(w.wall,1)} mm / 本体 ${fmt(w.pipeMass,3)} kg/m</p>
 <div class="twocol">${select(`${tag} 内容物`,base+'.fluidType',Object.entries(fluidCatalog).map(([k,v])=>[k,v.label]))}${p.fluidType==='empty'?'<div class="note">内容物重量 0 kg/m</div>':field(`${tag} 内容物の密度`,base+'.fluidDensity','kg/m³',.00001)}</div>
 ${fluid?`<div class="fluid-reference"><strong>${p.fluidType==='empty'?'空管':p.fluidDensitySource==='preset'?'参考初期値を使用中':p.fluidDensitySource==='legacy'?'従来の水・空管条件を使用':'手入力の密度を使用中'}</strong> ${esc(fluid.note)}${fluid.source?` <a href="${fluid.source.url}" target="_blank" rel="noopener">密度の参考資料 ↗</a>`:''}</div>`:''}
 ${['air','steam','heavyOil','custom'].includes(p.fluidType)?textField(`${tag} 密度の条件・根拠`,base+'.fluidCondition','運転温度・圧力（絶対圧／ゲージ圧）・製品名など'):''}
 <div class="pipe-mass-summary">本体 ${fmt(w.pipeMass,3)} ＋ 内容物 ${fmt(w.fluidMass,4)} ＋ 保温 ${fmt(w.insulationMass,3)} ＋ 追加 ${fmt(w.extraMass,3)} kg/m<br>負担長 ${fmt(w.tributary,3)} m → <strong>${fmt(w.load,4)} kN</strong></div></div>`:`<div class="twocol">${field(`${tag} 外径`,base+'.diameter','mm',1)}${field(`${tag} 荷重`,base+'.load','kN',0)}</div><p class="help">内容物・保温材等を含む、この架台1基が受け持つ荷重を入力してください。材質・サイズ・内容物から計算する場合は「自動計算」に切り替えます。</p>`}
 ${p.loadMode==='auto'?`<button class="small-btn pipe-detail-toggle" data-pipe-edit="${key}" aria-expanded="${editingPipe===key}">${editingPipe===key?'支持間隔・保温の詳細を閉じる':'支持間隔・保温・付属品を設定'}</button>${editingPipe===key?`<div class="pipe-settings"><div class="twocol">${field(`${tag} 支持間隔`,base+'.span','m',.01)}${select(`${tag} 支持位置・負担長`,base+'.supportCase',[['interior','等間隔の中間支持：間隔×1'],['end','単純支持の端部：間隔×1/2'],['custom','負担長を指定']])}</div>${p.supportCase==='custom'?field(`${tag} 架台が受け持つ長さ`,base+'.tributary','m',.01):''}
 ${select(`${tag} 保温材`,base+'.insulation',[['none','保温なし'],['nichias','ロックウール MGマイティカバー（平均90）'],['custom','保温材の密度を入力']])}${p.insulation!=='none'?`<div class="twocol">${field(`${tag} 保温厚さ`,base+'.insulationThickness','mm',0)}${field(`${tag} 保温材密度`,base+'.insulationDensity','kg/m³',1)}</div>${p.insulation==='nichias'?'<p class="help">メーカー平均密度90 kg/m³を初期値とします。実仕様・最大重量を確認して密度を調整してください。</p>':''}`:''}
 ${field(`${tag} 外装・付属品の追加単位質量`,base+'.extraMass','kg/m',0)}${w.source?`<p class="help"><a href="${w.source.url}" target="_blank" rel="noopener">${esc(w.source.label)} ↗</a>（${esc(w.source.page)}）</p>`:''}</div>`:''}`:''}
 ${w.error?`<div class="note danger">${esc(w.error)}</div>`:''}</div>`;
}
function rackTierEditor(){return panel('各段の配管重量と接合',`<div class="body"><div class="note">配管本体・選択した内容物・保温材を自動集計し、各配管の中心位置へ載荷します。支持間隔は配管の長手方向の距離です。負担長による一次検討で、連続管の正確な支持反力・熱応力等は含みません。架台自重は別に集計します。</div></div><div class="tier-grid weight-tier-grid">${s.rack.tiers.map((t,i)=>{let sum;try{sum=tierWeights(t);}catch{sum=null;}return `<section class="tier-card"><div class="tier-title"><strong><i></i>段 ${i+1}</strong><span>${t.pipes.length}本 / ${fmt(sum?.load,3)} kN</span></div>${field(s.mount==='ceiling'?`段${i+1} 天井からの距離`:`段${i+1} 高さ`,'rack.tiers.'+i+'.height','mm',1)}${tierJointEditor(t,i)}${sum?`<div class="tier-load">段荷重 <strong>${fmt(sum.load,3)} kN</strong><small>自動分：本体 ${fmt(sum.pipeKg,2)} / 内容物 ${fmt(sum.fluidKg,2)} / 保温 ${fmt(sum.insulationKg,2)} / 追加 ${fmt(sum.extraKg,2)} kg${sum.automatic?'':' ＋ 手入力荷重'}</small></div>`:''}${t.pipes.map((p,j)=>pipeConfig(i,j)).join('')}<div class="table-actions"><button class="small-btn" data-rack-add-pipe="${i}">＋ 段${i+1}に配管を追加</button><button class="small-btn" data-rack-space="${i}">均等配置</button></div></section>`;}).join('')}</div>`,`${s.rack.tiers.length}段 / ${s.rack.tiers.reduce((v,t)=>v+t.pipes.length,0)}本`,'full');}
function connectionResults(){return panel('梁端の接合部に伝わる力',`<div class="body"><div class="note">各段の梁端は柱および有効な先端縦材に接続します。溶接・ボルトと剛接・ピンの条件は、柱側・先端側それぞれに適用します。ボルト・接合板の仕様も接合位置ごとに個別に適用します。先端縦材は上下に連続する部材として扱います。接合仕様とは別に、剛接・ピンの力学条件を解析へ反映しています。下表は接合部全体の作用力で、ボルト1本あたりの力ではありません。ボルト・接合板の計算対象と結果は「ボルト接合」で確認できます。未照査項目があるため、接合部全体の合否は判定しません。</div></div><div class="table-wrap"><table><thead><tr><th>接合位置</th><th>方式</th><th>水平力 kN</th><th>鉛直力 kN</th><th>曲げ kN·m</th><th>ボルト仕様 / 本数</th></tr></thead><tbody>${result?.connections?.map(j=>`<tr><td>段${j.tier} / ${esc(j.endLabel||'接合部')} / X=${fmt(j.x,1)}</td><td>${esc(jointLabels[j.joint])}</td><td>${fmt(j.fx,3)}</td><td>${fmt(j.fy,3)}</td><td>${fmt(j.m,4)}</td><td>${j.joint==='weld'?'—':esc(j.boltSpec)+' / '+j.boltCount+'本 / '+boltStatus(j.boltCheck)}</td></tr>`).join('')||'<tr><td colspan="6">入力条件を確認してください。</td></tr>'}</tbody></table></div>`,'接合部全体の作用力','full');}
function pipeWeightReport(){if(s.geometryMode!=='dimensions')return '';return `<p><strong>配管自動荷重の算定</strong><br>W = (配管本体 ＋ 内径断面積×採用する内容物密度 ＋ 保温材円環体積×密度 ＋ 追加単位質量) × 負担長 × 9.80665 / 1000 [kN]。中間支持は支持間隔、単純支持の端部はその半分を負担長とする一次検討です。荷重倍率は解析で別途適用します。</p>${s.rack.tiers.map((t,i)=>{const tw=tierWeights(t);return `<p>段${i+1}：合計 ${fmt(tw.load,4)} kN / 接合位置別の条件<br>${boltEndSummary(t)}<br>溶接耐力は未照査。ボルト・板の計算対象は接合照査欄を参照。${esc(t.jointNote)}</p>${t.pipes.map((p,j)=>{const w=pipeWeight(p);return w.mode==='manual'?`<p>P${i+1}-${j+1}：手入力 ${fmt(w.load,4)} kN</p>`:`<p>P${i+1}-${j+1}：${esc(w.label)} / 外径 ${w.diameter} mm / 肉厚 ${w.wall} mm / 内径 ${fmt(w.id,2)} mm<br>支持間隔 ${p.span} m / ${({interior:'等間隔中間支持',end:'単純支持端部',custom:'負担長指定'})[p.supportCase]} / 負担長 ${w.tributary} m / 内容物 ${esc(w.fluid.label)}（採用密度 ρ=${w.fluid.fluidDensity} kg/m³）<br>密度の条件・根拠：${esc(p.fluidCondition)||'未記入'} / ${w.fluid.fluidDensitySource==='preset'?'参考初期値':w.fluid.fluidDensitySource==='legacy'?'従来の水・空管設定':'手入力'}${w.fluid.source?`<br>初期値の参考資料（採用密度の認証ではありません）：<a href="${w.fluid.source.url}">${esc(w.fluid.source.label)}</a> / ${esc(w.fluid.source.page)} / ${esc(w.fluid.note)}`:''}<br>保温 ${p.insulation==='none'?'なし':p.insulation==='nichias'?'MGマイティカバー':'任意材'} / 厚さ ${p.insulation==='none'?0:p.insulationThickness} mm / 密度 ${p.insulationDensity} kg/m³<br>本体 ${fmt(w.pipeMass,4)} / 内容物 ${fmt(w.fluidMass,4)} / 保温 ${fmt(w.insulationMass,4)} / 追加 ${fmt(w.extraMass,4)} kg/m<br>合計 ${fmt(w.totalMass,4)} kg/m × ${w.tributary} m = ${fmt(w.supportedMass,4)} kg → ${fmt(w.load,5)} kN${w.source?`<br>出典：<a href="${w.source.url}">${esc(w.source.label)}</a> / ${esc(w.source.page)} / ${esc(w.source.edition)}`:''}${p.insulation==='nichias'?`<br>保温密度参考：<a href="${pipeSources['nichias-rockwool'].url}">ニチアス ロックウールカタログ</a>（平均90 kg/m³、採用値は上記入力）`:''}</p>`;}).join('')}`;}).join('')}`;}

function boltStatus(c){return !c?'未計算':c.status==='outside'?'対象外・入力確認':c.status!=='checked'?'条件未確認':c.ratio>1?'計算対象に超過あり':'計算対象は範囲内';}
function boltOverview(){const cs=result?.connections?.filter(j=>j.joint!=='weld').map(j=>j.boltCheck)||[];if(!cs.length)return '未計算';if(cs.some(c=>!c||c.status!=='checked'))return '条件未確認または対象外';return `計算対象の最大比 ${fmt(Math.max(...cs.map(c=>c.ratio)),2)}（${cs.some(c=>c.ratio>1)?'超過あり':'範囲内'}）`  }
function boltNumSelect(label,path,items){return `<label class="field"><span>${label}</span><select data-path="${path}" data-number="true" aria-label="${label}">${options(items,val(path))}</select></label>`;}
function boltPlan(d,guideKey=''){let ps;try{ps=layoutBolts(d);}catch{return '<div class="note warning">配置を入力すると図を表示します。</div>';}if(![d.plateW,d.plateH,d.mateW,d.mateH,d.plateT,d.mateT,d.hole].every(v=>Number.isFinite(v)&&v>0))return '';const W=Math.max(d.plateW,d.mateW),H=Math.max(d.plateH,d.mateH),scale=Math.min(300/W,210/H),cx=210,cy=146,X=x=>cx+x*scale,Y=y=>cy-y*scale;return `<svg class="bolt-plan" viewBox="0 0 420 310" role="img" aria-label="接合板と相手材のボルト配置図"><rect x="${X(-d.plateW/2)}" y="${Y(d.plateH/2)}" width="${d.plateW*scale}" height="${d.plateH*scale}" fill="#eef5ef" stroke="#448775" stroke-width="2"/><rect x="${X(-d.mateW/2)}" y="${Y(d.mateH/2)}" width="${d.mateW*scale}" height="${d.mateH*scale}" fill="none" stroke="#ba9860" stroke-dasharray="5 4" stroke-width="2"/>${ps.map(p=>`<circle cx="${X(p.x)}" cy="${Y(p.y)}" r="${d.hole*scale/2}" fill="white" stroke="#387160"/><text x="${X(p.x)+d.hole*scale/2+3}" y="${Y(p.y)-4}" font-size="10" fill="#527367">${p.id}</text>`).join('')}<path d="M${cx-7} ${cy}h14 M${cx} ${cy-7}v14" stroke="#d88158"/><text x="210" y="24" text-anchor="middle" font-size="12" fill="#366854">${d.cols}列 × ${d.rows}段 ＝ ${boltCount(d)}本 ／ 正面XY</text><text x="210" y="278" text-anchor="middle" font-size="11" fill="#527367">接合板 ${d.plateW} × ${d.plateH} × t${d.plateT} mm</text><text x="210" y="299" text-anchor="middle" font-size="10" fill="#957745">破線：相手材 ／ ボルト軸は画面の手前・奥方向 Z</text>${guideKey?boltGuideOverlay(d,guideKey,scale,cx,cy):''}</svg>`;}
function boltDesignPage(){if(s.geometryMode!=='dimensions')return panel('ボルト接合',`<div class="body note">寸法入力モードの梁端接合を対象にしています。自由形状では接合位置・部材関係を自動判別できないため、耐力の自動照査は行いません。</div>`);selectedJointTier=Math.min(selectedJointTier,s.rack.tiers.length-1);const i=selectedJointTier,t=s.rack.tiers[i],ends=connectionPositions(s);if(!ends.some(e=>e.key===selectedJointEnd))selectedJointEnd=ends[0].key;t.boltDesigns=initializeBoltDesigns(t);t.jointTypes=initializeJointTypes(t);const end=ends.find(e=>e.key===selectedJointEnd),d=t.boltDesigns[end.key],joint=jointType(t,end.key),base=`rack.tiers.${i}.boltDesigns.${end.key}`,js=result?.connections?.filter(j=>j.tier===i+1&&j.endKey===end.key&&j.joint!=='weld')||[];const selector=`<label class="field"><span>設定する段</span><select data-joint-tier aria-label="設定する段">${options(s.rack.tiers.map((t,j)=>[j,`段${j+1} / ${t.height} mm`]),i)}</select></label><label class="field"><span>設定する接合位置</span><select data-joint-end aria-label="設定する接合位置">${options(ends.map(e=>[e.key,`${e.label} / X=${e.x} mm`]),end.key)}</select></label>${select(`段${i+1} ${end.label}の接合条件`,`rack.tiers.${i}.jointTypes.${end.key}`,Object.entries(jointLabels))}`;if(joint==='weld')return panel('接合条件を設定',`<div class="body">${selector}${boltEndCards(t,i,ends,end.key)}<div class="note"><strong>編集中：段${i+1}・${esc(end.label)}</strong><br>この位置は溶接・剛接として曲げを伝達します。溶接部の耐力は未照査です。他の接合位置は、それぞれの条件で計算します。ボルト接合へ変更すると、この位置のボルト・接合板を設定できます。</div>${connectionResults()}</div>`);
 const gradeOpts=d.method==='bearing'?Object.entries(ordinaryGrades).map(([k,v])=>[k,v.label]):[['F10T','高力六角 F10T'],['S10T','トルシア形 S10T']],diameters=d.method==='bearing'?Object.keys(boltSizes).map(Number):Object.keys(slipTable).map(Number).filter(v=>d.grade!=='S10T'||v!==12);
 return `<div class="detailgrid bolt-design-grid"><div>${panel('ボルト・接合板を設定',`<div class="body">${selector}${boltEndCards(t,i,ends,end.key)}<div class="note"><strong>編集中：段${i+1}・${esc(end.label)}</strong><br>この接合位置だけに適用します。材質・径・本数・配置・板厚と、普通／摩擦接合をそれぞれ設定できます。溶接・ボルトと剛接・ピンの条件も、この位置だけに適用します。側板の面内接合が対象です。端板を柱正面へ留めてボルトが引張を受ける形式には使えません。${joint==='bolt-rigid'?'剛接の回転剛性はこの耐力計算では確認しません。':''}</div><div class="sep"></div>${select('接合方式',base+'.method',[['bearing','普通ボルト・支圧接合'],['friction','高力ボルト・摩擦接合']])}${select('ボルトの材質・強度区分',base+'.grade',gradeOpts)}<div class="twocol">${boltNumSelect('ボルト径',base+'.diameter',diameters.map(v=>[v,'M'+v]))}${select('荷重区分',base+'.period',[['long','長期'],['short','短期']])}</div>${boltNumSelect('せん断・摩擦の伝達面数',base+'.planes',[[1,'1面：接合板＋相手材'],[2,'2面：同じ接合板2枚＋中央の相手材']])}<p class="help">2面は同じ外板2枚が均等に負担する対称配置です。相手材は全荷重、外板は各1/2で照査します。</p><div class="section-label">本数と配置（群中心を原点）</div><div class="twocol">${field('横方向の本数（列）',base+'.cols','本',1,1)}${field('縦方向の本数（段）',base+'.rows','本',1,1)}${field('横ピッチ',base+'.pitchX','mm',0)}${field('縦ピッチ',base+'.pitchY','mm',0)}${field('正円の孔径',base+'.hole','mm',1)}</div><div class="note">1接合あたり <strong>${boltCount(d)}本</strong>。等間隔の矩形配置、全周縁端距離2.5d以上を本アプリの対応範囲とします。千鳥・長孔・皿ボルトは対象外です。</div><div class="twocol">${field('節点から群中心まで ΔX',base+'.offsetX','mm')}${field('節点から群中心まで ΔY',base+'.offsetY','mm')}</div><p class="help">架台図のX右向き・Y上向き。選択した接合位置からボルト群中心までの距離を入力します。柱側と先端側で別の値・符号を設定できます。</p>${['plate','mate'].map((p,j)=>`<div class="section-label">${j?'相手材の有効重ね部':'接合板'}（群中心に対称）</div>${select(j?'相手材の材質':'接合板の材質',base+'.'+p+'Material',[['SS400','SS400'],['SUS304','SUS304（材料強度の参考評価）']])}<div class="threecol">${field(j?'相手材の厚さ':'接合板の厚さ',base+'.'+p+'T','mm',3)}${field(j?'相手材の有効幅':'接合板の幅',base+'.'+p+'W','mm',1)}${field(j?'相手材の有効高さ':'接合板の高さ',base+'.'+p+'H','mm',1)}</div>`).join('')}<p class="help">3〜40 mmの板厚が対象。形鋼の全幅ではなく、孔の周囲で実際に力を伝える有効な板部分を入力します。160 mm等の初期値は入力例で、選んだ形鋼から自動決定した寸法ではありません。</p>${d.method==='friction'?`${select('摩擦面の仕上げ',base+'.frictionSurface',[['standard','標準摩擦面（黒皮除去・所定処理）'],['coated','塗装・めっき面（対象外）'],['other','その他（対象外）']])}${field('資料で確認したすべり係数',base+'.slipCoefficient','',.01,.01)}${checkbox(base+'.frictionConfirmed','摩擦面処理・すべり係数・所定締付けを確認した')}<p class="help">係数0.45以上、SS400同士の登録表を使用。0.45を超えても耐力を割増しません。</p>`:''}${checkbox(base+'.scopeConfirmed','面内接合で、ボルト軸方向引張・面外偏心がない')}${checkbox(base+'.fitConfirmed','両材の実寸法と孔配置が納まり、力を伝達できる')}${d.period==='short'?checkbox(base+'.loadCaseConfirmed','地震等を含む短期荷重の組合せを別途設定した'):''}${textField('仕様・納まりの確認資料',base+'.evidence','図面番号・ボルト仕様・摩擦面の確認資料等')}<div class="note warning">${jointLimitations.map(esc).join('<br>')}</div></div>`,'寸法 mm ／ 耐力 kN')}</div><div class="bolt-preview">${panel(`${esc(end.label)}の接合部配置`,`<div class="body">${boltPlan(d)}</div>`,'入力寸法に連動')}${js.map(j=>boltResultCard(j)).join('')}${panel('計算式・出典',`<div class="body">${boltMethod()}${boltSourceLinks([...new Set(js.flatMap(j=>j.boltCheck?.sources||[]))])}</div>`,'参考一次照査','full')}</div></div>`;
}
function boltSourceLinks(keys){return `<ul class="help">${keys.map(k=>jointSources[k]?`<li><a href="${jointSources[k].url}" target="_blank" rel="noopener">${esc(jointSources[k].title)}</a> — ${esc(jointSources[k].page)}</li>`:'').join('')}</ul>`;}
function boltMethod(){return `<div class="method">各ボルトは同じ剛性とし、直接せん断と群中心まわりのモーメントを弾性分配します。J=Σ(x²+y²)、M群=M節点−ΔX·Fy＋ΔY·Fx、qx=Fx/n−M群·y/J、qy=Fy/n＋M群·x/J。<br>普通ボルト：As·F/(1.5√3)×せん断面数。高力摩擦：メーカー許容力表。板の支圧：1.25F·d·t。長期の板断面限度：σa=F/1.5、τa=F/(1.5√3)。短期は1.5倍（高力摩擦は短期表を直接使用）。<br>板断面は正円孔の最大欠損幅を差し引き、σ=|N|/An＋|M|/Zn、τ=1.5|V|/An、σ/σa＋τ/τa を参考表示します。X・Y両方向の孔を通る断面と外周総断面へ、全作用力と偏心モーメントの包絡を適用します。端抜け・ブロック破断を含む耐力ではありません。</div>`;}
function boltResultCard(j){const c=j.boltCheck;if(!c)return '';return panel(`段${j.tier} / ${esc(j.endLabel||'接合部')} / X=${fmt(j.x,1)} mm`, `<div class="body"><div class="bolt-result-head"><strong>${boltStatus(c)}</strong><span class="badge pending">接合部全体は未判定</span></div><p class="help">作用力：Fx ${fmt(j.fx,3)} kN ／ Fy ${fmt(j.fy,3)} kN ／ M ${fmt(j.m,4)} kN·m<br>群中心まわり M ${fmt(c.M/1e6,4)} kN·m ／ ボルト本数 ${c.points.length}本</p>${c.issues.length?`<div class="note warning">${c.issues.map(esc).join('<br>')}<br>下の許容値は条件付きの参考値で、照査への採用は保留です。</div>`:''}${c.allowable?`<div class="capacity-values"><div><span>1本の${c.design.method==='friction'?'摩擦':'せん断'}許容力</span><strong>${fmt(c.allowable,2)} <small>kN</small></strong></div><div><span>最大のボルト負担</span><strong>${fmt(Math.max(...c.points.map(p=>p.q)),2)} <small>kN</small></strong></div></div>`:''}<div class="help">${c.advisories.map(esc).join('<br>')}</div></div><div class="table-wrap"><table><thead><tr><th>計算対象</th><th>作用 / 許容</th><th>比率</th></tr></thead><tbody>${c.checks.map(q=>`<tr><td>${esc(q.name)}</td><td>${fmt(q.demand,3)} / ${fmt(q.capacity,3)} ${esc(q.unit)}</td><td>${c.status==='checked'?`<span class="badge ${q.ratio>1?'red':'pending'}">${fmt(q.ratio,3)}</span>`:'—（未採用）'}</td></tr>`).join('')}</tbody></table></div><details class="bolt-detail"><summary>各ボルトの負担・板断面値</summary><div class="table-wrap"><table><thead><tr><th>番号</th><th>X / Y mm</th><th>qx / qy kN</th><th>合成 kN</th></tr></thead><tbody>${c.points.map(p=>`<tr><td>${p.id}</td><td>${fmt(p.x,1)} / ${fmt(p.y,1)}</td><td>${fmt(p.qx,3)} / ${fmt(p.qy,3)}</td><td>${fmt(p.q,3)}</td></tr>`).join('')}</tbody></table></div><p class="help">${c.plate.map(p=>`${p.prefix==='plate'?'接合板':'相手材'}：F=${p.strength.F} MPa / An(X/Y)=${fmt(p.netX,1)}/${fmt(p.netY,1)} mm² / I(X/Y)=${fmt(p.Ix,0)}/${fmt(p.Iy,0)} mm⁴ / 負担率${p.share}`).join('<br>')}</p></details>`, 'ボルト・板の計算対象','full');}
function boltReport(){if(s.geometryMode!=='dimensions')return '';const js=result?.connections?.filter(j=>j.joint!=='weld')||[];if(!js.length)return '';return `<div class="bolt-report"><h3>ボルト接合の耐力（側板・面内の一次照査）</h3><p>${jointLimitations.map(esc).join('<br>')}</p>${js.map(j=>{const raw=j.boltDesign,d=Object.fromEntries(Object.entries(raw).map(([k,v])=>[k,typeof v==='string'?esc(v):v]));return `<p><strong>段${j.tier}・${esc(j.endLabel)} / X=${fmt(j.x,1)} mm の仕様</strong>：${esc(jointLabels[j.joint])} / ${esc(boltLabel(d))} / ${d.method==='friction'?'摩擦接合':'普通ボルト支圧接合'} / ${d.period==='long'?'長期':'短期'} / ${d.planes}面<br>${d.cols}列×${d.rows}段=${boltCount(d)}本 / ピッチX=${d.pitchX}, Y=${d.pitchY} mm / 孔径${d.hole} mm / 群中心偏心ΔX=${d.offsetX}, ΔY=${d.offsetY} mm<br>接合板：${d.plateMaterial} ${d.plateW}×${d.plateH}×t${d.plateT} mm / 相手材：${d.mateMaterial} ${d.mateW}×${d.mateH}×t${d.mateT} mm<br>面内条件確認 ${d.scopeConfirmed?'済':'未'} / 納まり確認 ${d.fitConfirmed?'済':'未'}${d.method==='friction'?` / 摩擦面${esc(d.frictionSurface)} / すべり係数${d.slipCoefficient} / 処理・締付け確認${d.frictionConfirmed?'済':'未'}`:''}<br>確認資料：${esc(d.evidence)||'未記入'}</p>${boltPlan(d)}`;}).join('')}${js.map(boltResultCard).join('')}${boltMethod()}${boltSourceLinks([...new Set(js.flatMap(j=>j.boltCheck?.sources||[]))])}</div>`;}
function tierJointEditor(t,i){t.jointTypes=initializeJointTypes(t);return `<div class="section-label">接合位置ごとの条件</div>${connectionPositions(s).map(e=>select(`段${i+1} ${e.label}の接合条件`,`rack.tiers.${i}.jointTypes.${e.key}`,Object.entries(jointLabels))).join('')}<div class="note">${boltEndSummary(t)}<br>剛接は曲げを伝達、ピンは回転自由として解析します。<br><button class="small-btn" data-bolt-tier="${i}">段${i+1}の接合詳細・ボルト耐力</button></div>`;}
function boltEndSummary(t){return connectionPositions(s).map(e=>{const d=normalizeBoltDesign(t,e.key),joint=jointType(t,e.key);return `${esc(e.label)}：${esc(jointLabels[joint])}${joint==='weld'?' / 溶接耐力は未照査':` / ${esc(boltLabel(d))} / ${boltCount(d)}本 / 接合板 t${fmt(d.plateT,1)} mm`}`;}).join('<br>');}
function boltEndCards(t,i,ends,selectedEnd){return `<div class="bolt-end-cards">${ends.map(e=>{const d=normalizeBoltDesign(t,e.key),joint=jointType(t,e.key);return `<button class="bolt-end-card ${selectedEnd===e.key?'selected':''}" data-bolt-tier="${i}" data-bolt-end="${e.key}" aria-label="段${i+1} ${esc(e.label)}を編集"><strong>${esc(e.label)}</strong><span>${esc(jointLabels[joint])}</span>${joint==='weld'?'<small>曲げを伝達<br>溶接耐力は未照査</small>':`<span>${esc(boltLabel(d))} ／ ${boltCount(d)}本</span><small>${d.method==='friction'?'摩擦接合':'支圧接合'} ／ ピッチ ${fmt(d.pitchX,0)}×${fmt(d.pitchY,0)} mm<br>接合板 t${fmt(d.plateT,1)} mm</small>`}</button>`;}).join('')}</div>`;}

function currentInputContext(){let path=activeInput.tab===tab?activeInput.path:'',label=activeInput.tab===tab?activeInput.label:'';if(tab==='bolts'&&s.geometryMode==='dimensions'){const end=connectionPositions(s).find(e=>e.key===selectedJointEnd)||connectionPositions(s)[0];if(!path.startsWith(`rack.tiers.${selectedJointTier}.`)||!path.includes(`.${end.key}`)){path=`rack.tiers.${selectedJointTier}.jointTypes.${end.key}`;label='接合条件';}}return inputContext(s,path,label);}
function workspaceContent(){const content=tab==='geometry'?geometry():tab==='material'?material():tab==='loads'?loads():tab==='anchor'?anchor():tab==='bolts'?boltDesignPage():report();if(tab==='report')return content;return `<div class="guided-workspace"><aside id="input-guide" class="input-guide ${guideCollapsed?'collapsed':''}" aria-label="入力位置ガイド">${inputGuide()}</aside><div class="guided-content">${content}</div></div>`;}
function inputGuide(){const c=currentInputContext();let detail='';if(tab==='bolts'&&s.geometryMode==='dimensions'){const t=s.rack.tiers[selectedJointTier],end=connectionPositions(s).find(e=>e.key===selectedJointEnd)||connectionPositions(s)[0];if(t&&jointType(t,end.key)!=='weld')detail=boltPlan(normalizeBoltDesign(t,end.key),activeInput.tab===tab?activeInput.path.split('.').at(-1):'');}if(tab==='material'){try{detail=sectionDrawing(section(s,selected));}catch{}}
 const fresh=modelSvg(true).replaceAll('hatch','guide-hatch').replaceAll('arrow','guide-arrow');if(!error)lastGuideSvg=fresh;const graph=error&&lastGuideSvg?lastGuideSvg:fresh;return `<div class="guide-heading"><strong>入力位置ガイド</strong><button class="small-btn" data-action="toggle-guide" aria-expanded="${!guideCollapsed}">${guideCollapsed?'図を表示':'図を小さく畳む'}</button></div><div class="guide-context" role="status"><span>入力対象</span><strong>${esc(c.title)}</strong></div><div class="guide-visuals ${detail?'with-detail':''}"><div>${graph}</div>${detail?`<div class="guide-detail">${detail}</div>`:''}</div><p class="guide-hint">${esc(c.hint)}</p>${error?'<div class="guide-error">入力条件を確認してください。図は直前の有効な状態です（未更新）。</div>':''}`;}
function updateInputGuide(){const el=document.getElementById('input-guide');if(!el)return;el.classList.toggle('collapsed',guideCollapsed);el.innerHTML=inputGuide();}
